    .nav-right a:hover { color: var(--brand); }
    .theme-toggle {
      width: 40px; height: 40px; display: grid; place-items: center; cursor: pointer;
      border: 1px solid var(--border); border-radius: 10px; background: var(--surface); color: var(--text);
    }
    [data-theme="light"] .icon-sun, [data-theme="dark"] .icon-moon { display: none; }

    .hero { padding: clamp(3rem, 9vw, 6rem) 0 3rem; }
    .hero small { color: var(--brand); font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
    .hero h1 { font-size: clamp(2.2rem, 6vw, 3.8rem); line-height: 1.1; margin: .5rem 0 1rem; letter-spacing: -.03em; }
    .hero p { max-width: 38rem; color: var(--muted); font-size: 1.1rem; }
    .skills { display: flex; flex-wrap: wrap; gap: .5rem; padding: 0; margin: 1.5rem 0 0; list-style: none; }
    .skills li { padding: .3rem .8rem; border-radius: 999px; background: var(--brand-soft); color: var(--brand); font-weight: 600; font-size: .9rem; }

    section { padding: 3rem 0; }
    h2 { font-size: clamp(1.6rem, 3vw, 2.2rem); margin: 0 0 1.25rem; letter-spacing: -.02em; }

    .filters { display: flex; flex-wrap: wrap; gap: .5rem; margin-bottom: .75rem; }
    .chip {
      padding: .45rem 1rem; border-radius: 999px; border: 1px solid var(--border); cursor: pointer;
      background: var(--surface); color: var(--muted); font: inherit; font-size: .9rem; font-weight: 600;
    }
    .chip[aria-pressed="true"] { background: var(--brand); border-color: var(--brand); color: #fff; }
    .result-count { color: var(--muted); font-size: .9rem; margin: 0 0 1.25rem; }
    .projects { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 1.25rem; }
    .project {
