    .tags { display: flex; flex-wrap: wrap; gap: .4rem; padding: 0; margin: 0 0 1rem; list-style: none; }
    .tags li { font-size: .78rem; padding: .15rem .55rem; border-radius: 6px; background: var(--brand-soft); color: var(--brand); font-weight: 600; }
    .links { display: flex; gap: 1rem; font-weight: 600; }

    form { display: grid; gap: 1rem; max-width: 560px; }
    label { font-weight: 600; display: block; margin-bottom: .35rem; }
    input, textarea {
      width: 100%; padding: .75rem .9rem; border-radius: 10px; font: inherit;
      border: 1px solid var(--border); background: var(--surface); color: var(--text);
    }
    textarea { min-height: 140px; resize: vertical; }
    [aria-invalid="true"] { border-color: var(--danger); }
    .error { color: var(--danger); font-size: .88rem; margin: .3rem 0 0; min-height: 1.2em; }
    .btn {
      justify-self: start; padding: .8rem 1.6rem; border: 0; border-radius: 10px; cursor: pointer;
      background: var(--brand); color: #fff; font: inherit; font-weight: 700;
    }
    .btn:disabled { opacity: .6; cursor: progress; }
    .form-status { margin: 0; font-weight: 600; color: var(--success); }
    footer { padding: 2rem 0; color: var(--muted); font-size: .9rem; border-top: 1px solid var(--border); }

    @media (max-width: 560px) {
      .nav-right a { display: none; }
    }
    @media (prefers-reduced-motion: reduce) {
      * { transition: none !important; }
    }
  </style>
</head>
<body>
  <header>
