  <script>
    // ----- Tema -----
    const root = document.documentElement;
    const themeToggle = document.getElementById('theme-toggle');

    function applyTheme(theme) {
      root.dataset.theme = theme;
      themeToggle.setAttribute('aria-label', theme === 'dark' ? 'Ganti ke mode terang' : 'Ganti ke mode gelap');
    }
    themeToggle.addEventListener('click', () => {
      const next = root.dataset.theme === 'dark' ? 'light' : 'dark';
      applyTheme(next);
      try { localStorage.setItem('theme', next); } catch (e) { /* abaikan */ }
    });
    applyTheme(root.dataset.theme);

    // ----- Proyek -----
    // Ganti URL example.com dengan tautan demo dan repositori milikmu.
    const PROJECTS = [
      { title: 'Kasir UMKM', desc: 'Aplikasi kasir berbasis web dengan laporan penjualan harian dan stok otomatis.', tags: ['React', 'Node.js', 'PostgreSQL'], demo: 'https://example.com/kasir', repo: 'https://example.com/kasir-repo' },
      { title: 'SiPerpus', desc: 'Sistem peminjaman buku perpustakaan sekolah dengan pengingat jatuh tempo.', tags: ['Laravel', 'MySQL'], demo: 'https://example.com/siperpus', repo: 'https://example.com/siperpus-repo' },
      { title: 'Cuaca Kita', desc: 'Dashboard prakiraan cuaca dengan grafik suhu per jam dan mode offline.', tags: ['Vue', 'TypeScript'], demo: 'https://example.com/cuaca', repo: 'https://example.com/cuaca-repo' },
      { title: 'Toko Batik Online', desc: 'Toko online dengan katalog, keranjang, dan pembayaran terintegrasi.', tags: ['React', 'TypeScript', 'Node.js'], demo: 'https://example.com/batik', repo: 'https://example.com/batik-repo' },
      { title: 'Chat Layanan Pelanggan', desc: 'Chat realtime untuk tim CS dengan riwayat percakapan dan label prioritas.', tags: ['Vue', 'Node.js'], demo: 'https://example.com/chat', repo: 'https://example.com/chat-repo' },
      { title: 'Portal Koperasi Tani', desc: 'Situs informasi harga panen dan jadwal pertemuan anggota koperasi.', tags: ['Laravel', 'PostgreSQL'], demo: 'https://example.com/koperasi', repo: 'https://example.com/koperasi-repo' }
    ];

    const filtersEl = document.getElementById('filters');
    const projectsEl = document.getElementById('projects');
    const countEl = document.getElementById('result-count');
    const ALL = 'Semua';
    const tags = [ALL, ...new Set(PROJECTS.flatMap((p) => p.tags))].sort((a, b) => (a === ALL ? -1 : b === ALL ? 1 : a.localeCompare(b)));
    let activeTag = ALL;

    function el(tag, props = {}, children = []) {
      const node = Object.assign(document.createElement(tag), props);
      node.append(...children);
      return node;
    }

    function renderFilters() {
      filtersEl.replaceChildren(...tags.map((tag) => {
        const chip = el('button', { type: 'button', className: 'chip', textContent: tag });
        chip.setAttribute('aria-pressed', String(tag === activeTag));
        chip.addEventListener('click', () => { activeTag = tag; renderFilters(); renderProjects(); });
        return chip;
      }));
    }

    function renderProjects() {
      const list = activeTag === ALL ? PROJECTS : PROJECTS.filter((p) => p.tags.includes(activeTag));
      projectsEl.replaceChildren(...list.map((p) => el('article', { className: 'project' }, [
        el('h3', { textContent: p.title }),
        el('p', { textContent: p.desc }),
        el('ul', { className: 'tags' }, p.tags.map((t) => el('li', { textContent: t }))),
        el('div', { className: 'links' }, [
          el('a', { href: p.demo, textContent: 'Lihat demo', target: '_blank', rel: 'noopener' }),
          el('a', { href: p.repo, textContent: 'Kode sumber', target: '_blank', rel: 'noopener' })
        ])
      ])));
      countEl.textContent = activeTag === ALL
        ? `Menampilkan semua ${list.length} proyek`
        : `Menampilkan ${list.length} proyek dengan ${activeTag}`;
    }

    renderFilters();
    renderProjects();

    // ----- Form kontak -----
    const form = document.getElementById('contact-form');
    const statusEl = document.getElementById('form-status');
    const RULES = {
      name: (v) => (v.trim().length >= 2 ? '' : 'Nama minimal 2 karakter.'),
      email: (v) => (/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()) ? '' : 'Masukkan alamat email yang valid.'),
      message: (v) => (v.trim().length >= 20 ? '' : 'Pesan minimal 20 karakter supaya saya paham kebutuhanmu.')
    };

    function validateField(input) {
      const message = RULES[input.name](input.value);
      input.setAttribute('aria-invalid', String(Boolean(message)));
      document.getElementById(`${input.name}-error`).textContent = message;
      return !message;
    }

    form.addEventListener('input', (e) => {
      if (e.target.getAttribute('aria-invalid') === 'true') validateField(e.target);
    });

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      statusEl.textContent = '';
      const fields = [...form.querySelectorAll('input, textarea')];
      const results = fields.map(validateField);
      const firstInvalid = fields[results.indexOf(false)];
      if (firstInvalid) {
        firstInvalid.focus();
        return;
      }
      const button = form.querySelector('button[type="submit"]');
      button.disabled = true;
      // Ganti simulasi ini dengan fetch() ke backend atau layanan form pilihanmu.
      await new Promise((resolve) => setTimeout(resolve, 600));
      button.disabled = false;
      form.reset();
      fields.forEach((f) => f.removeAttribute('aria-invalid'));
      statusEl.textContent = 'Terima kasih! Pesanmu sudah terkirim. Saya akan membalas dalam 1–2 hari kerja.';
    });

    document.getElementById('year').textContent = new Date().getFullYear();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Portfolio Raka Pratama** → hero perkenalan, daftar proyek, dan bagian kontak.
- **Dark mode** → tombol `#theme-toggle` dan `applyTheme()`. Bawaannya mengikuti pengaturan sistem, pilihan diingat di `localStorage`, dan tema dipasang di `<head>` sebelum halaman dirender sehingga tidak ada kedipan putih.
- **Filter proyek berdasarkan teknologi** → `renderFilters()` membuat tombol dari semua teknologi di `PROJECTS` (dengan `aria-pressed`), lalu `renderProjects()` menampilkan hasil beserta jumlahnya.
- **Form kontak dengan validasi** → `RULES` dan `validateField()` memeriksa setiap kolom. Pesan error terhubung ke input lewat `aria-describedby`, dan fokus pindah ke kolom pertama yang salah.

**Catatan**
- Semua konten dinamis dibuat dengan `textContent`, sehingga aman dari injeksi HTML.
- Ganti simulasi pengiriman di handler `submit` dengan `fetch()` ke backend atau layanan form pilihanmu.

Berikut aplikasi to-do list dalam satu file HTML. Data tersimpan di `localStorage`, jadi tugas tetap ada walaupun halaman dimuat ulang.

```html
<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Daftar Tugas</title>
  <style>
    :root {
      --bg: #f1f5f9; --card: #ffffff; --text: #0f172a; --muted: #64748b;
      --border: #e2e8f0; --brand: #0d9488; --brand-dark: #0f766e; --danger: #dc2626;
    }
    *, *::before, *::after { box-sizing: border-box; }
    body {
      margin: 0; min-height: 100vh; padding: clamp(1.5rem, 6vw, 4rem) 1rem;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      background: var(--bg); color: var(--text);
    }
    .app { max-width: 560px; margin: 0 auto; background: var(--card); border-radius: 18px; box-shadow: 0 20px 45px rgba(15, 23, 42, .08); overflow: hidden; }
    header { padding: 1.75rem 1.5rem 1rem; }
    h1 { margin: 0; font-size: 1.6rem; }
    .subtitle { margin: .25rem 0 0; color: var(--muted); }
    :focus-visible { outline: 3px solid var(--brand); outline-offset: 2px; }

    .new-todo { display: flex; gap: .5rem; padding: 0 1.5rem 1.25rem; }
    .new-todo input {
      flex: 1; min-width: 0; padding: .8rem 1rem; border: 1px solid var(--border); border-radius: 10px; font: inherit;
    }
    .btn {
      padding: .8rem 1.2rem; border: 0; border-radius: 10px; cursor: pointer;
      background: var(--brand); color: #fff; font: inherit; font-weight: 600;
    }
    .btn:hover { background: var(--brand-dark); }

    .filters { display: flex; gap: .25rem; padding: .5rem 1.5rem; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
    .filters button {
      padding: .4rem .9rem; border: 0; border-radius: 999px; cursor: pointer;
      background: transparent; color: var(--muted); font: inherit; font-weight: 600;
    }
    .filters button[aria-pressed="true"] { background: #ccfbf1; color: var(--brand-dark); }

    ul { list-style: none; margin: 0; padding: 0; }
    .todo { display: flex; align-items: center; gap: .75rem; padding: .85rem 1.5rem; border-bottom: 1px solid var(--border); }
    .todo input[type="checkbox"] { width: 1.2rem; height: 1.2rem; accent-color: var(--brand); flex-shrink: 0; }
    .todo .text { flex: 1; min-width: 0; overflow-wrap: anywhere; }
    .todo.done .text { text-decoration: line-through; color: var(--muted); }
    .todo .edit-input { flex: 1; min-width: 0; padding: .45rem .6rem; font: inherit; border: 1px solid var(--brand); border-radius: 8px; }
    .icon-btn {
      display: grid; place-items: center; width: 34px; height: 34px; flex-shrink: 0;
      border: 0; border-radius: 8px; background: transparent; color: var(--muted); cursor: pointer;
    }
    .icon-btn:hover { background: var(--bg); color: var(--text); }
    .icon-btn.delete:hover { color: var(--danger); }
    .empty { padding: 2.5rem 1.5rem; text-align: center; color: var(--muted); }

    footer { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 1rem 1.5rem; color: var(--muted); font-size: .9rem; }
    .link-btn { border: 0; background: none; color: var(--danger); font: inherit; cursor: pointer; padding: 0; }
    .link-btn:disabled { color: var(--border); cursor: default; }
    .sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
  </style>
</head>
<body>
  <main class="app">
    <header>
      <h1>Daftar Tugas</h1>
      <p class="subtitle">Klik dua kali pada tugas atau tekan ikon pensil untuk mengedit.</p>
    </header>

    <form class="new-todo" id="new-todo">
      <label for="new-text" class="sr-only">Tugas baru</label>
      <input id="new-text" placeholder="Mau mengerjakan apa hari ini?" maxlength="200" autocomplete="off" required>
      <button class="btn" type="submit">Tambah</button>
    </form>

    <div class="filters" role="group" aria-label="Filter tugas">
      <button type="button" data-filter="all" aria-pressed="true">Semua</button>
      <button type="button" data-filter="active" aria-pressed="false">Aktif</button>
      <button type="button" data-filter="done" aria-pressed="false">Selesai</button>
    </div>

    <ul id="todo-list" aria-label="Daftar tugas"></ul>

    <footer>
      <span id="counter" aria-live="polite"></span>
      <button class="link-btn" type="button" id="clear-done">Hapus yang selesai</button>
    </footer>
  </main>

  <script>
    const STORAGE_KEY = 'todo-app-v1';
    const listEl = document.getElementById('todo-list');
    const counterEl = document.getElementById('counter');
    const clearBtn = document.getElementById('clear-done');
    const form = document.getElementById('new-todo');
    const input = document.getElementById('new-text');
    const filterButtons = document.querySelectorAll('[data-filter]');

    let todos = load();
    let filter = 'all';
    let editingId = null;

    function load() {
      try {
        const data = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
        return Array.isArray(data) ? data.filter((t) => t && typeof t.text === 'string') : [];
      } catch (e) {
        return [];
      }
    }

    function save() {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
      } catch (e) {
        // Storage penuh atau diblokir: data tetap ada selama tab masih terbuka.
      }
    }

    const newId = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);

    function visibleTodos() {
      if (filter === 'active') return todos.filter((t) => !t.done);
      if (filter === 'done') return todos.filter((t) => t.done);
      return todos;
    }

    const ICONS = {
      edit: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"/></svg>',
      delete: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2M19 6l-1 14H6L5 6"/></svg>'
    };

    function render() {
      const items = visibleTodos();
      listEl.replaceChildren();

      if (items.length === 0) {
        const empty = document.createElement('li');
        empty.className = 'empty';
        empty.textContent = todos.length === 0 ? 'Belum ada tugas. Tambahkan yang pertama!' : 'Tidak ada tugas di filter ini.';
        listEl.append(empty);
      }

      for (const todo of items) {
        const li = document.createElement('li');
        li.className = 'todo' + (todo.done ? ' done' : '');
        li.dataset.id = todo.id;

        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = todo.done;
        checkbox.className = 'toggle';
        checkbox.setAttribute('aria-label', `Tandai "${todo.text}" selesai`);

        let textEl;
        if (todo.id === editingId) {
          textEl = document.createElement('input');
          textEl.className = 'edit-input';
          textEl.value = todo.text;
          textEl.maxLength = 200;
          textEl.setAttribute('aria-label', 'Edit tugas');
        } else {
          textEl = document.createElement('span');
          textEl.className = 'text';
          textEl.textContent = todo.text;
        }

        const editBtn = document.createElement('button');
        editBtn.type = 'button';
        editBtn.className = 'icon-btn edit';
        editBtn.innerHTML = ICONS.edit;
        editBtn.setAttribute('aria-label', `Edit "${todo.text}"`);

        const deleteBtn = document.createElement('button');
        deleteBtn.type = 'button';
        deleteBtn.className = 'icon-btn delete';
        deleteBtn.innerHTML = ICONS.delete;
        deleteBtn.setAttribute('aria-label', `Hapus "${todo.text}"`);

        li.append(checkbox, textEl, editBtn, deleteBtn);
        listEl.append(li);
      }

      const active = todos.filter((t) => !t.done).length;
      const done = todos.length - active;
      counterEl.textContent = `${active} tugas tersisa`;
      clearBtn.disabled = done === 0;
      filterButtons.forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.filter === filter)));

      const editInput = listEl.querySelector('.edit-input');
      if (editInput) {
        editInput.focus();
        editInput.setSelectionRange(editInput.value.length, editInput.value.length);
      }
    }

    function update(id, changes) {
      todos = todos.map((t) => (t.id === id ? { ...t, ...changes } : t));
      save();
      render();
    }

    function remove(id) {
      todos = todos.filter((t) => t.id !== id);
      save();
      render();
    }

    function finishEdit(id, value, commit) {
      if (editingId !== id) return;
      editingId = null;
      if (!commit) return render();
      const text = value.trim();
      if (text) update(id, { text });
      else remove(id);
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const text = input.value.trim();
      if (!text) return;
      todos.unshift({ id: newId(), text, done: false });
      input.value = '';
      save();
      render();
    });

    listEl.addEventListener('change', (e) => {
      if (!e.target.classList.contains('toggle')) return;
      update(e.target.closest('.todo').dataset.id, { done: e.target.checked });
    });

    listEl.addEventListener('click', (e) => {
      const li = e.target.closest('.todo');
      if (!li) return;
      if (e.target.closest('.delete')) remove(li.dataset.id);
      if (e.target.closest('.edit')) { editingId = li.dataset.id; render(); }
    });

    listEl.addEventListener('dblclick', (e) => {
      if (!e.target.classList.contains('text')) return;
      editingId = e.target.closest('.todo').dataset.id;
      render();
    });

    listEl.addEventListener('keydown', (e) => {
      if (!e.target.classList.contains('edit-input')) return;
      const id = e.target.closest('.todo').dataset.id;
      if (e.key === 'Enter') finishEdit(id, e.target.value, true);
      if (e.key === 'Escape') finishEdit(id, e.target.value, false);
    });

    listEl.addEventListener('focusout', (e) => {
      if (!e.target.classList.contains('edit-input')) return;
      finishEdit(e.target.closest('.todo').dataset.id, e.target.value, true);
    });

    filterButtons.forEach((button) => button.addEventListener('click', () => {
      filter = button.dataset.filter;
      render();
    }));

    clearBtn.addEventListener('click', () => {
      todos = todos.filter((t) => !t.done);
      save();
      render();
    });

    render();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Satu file HTML** → HTML, CSS, dan JavaScript dalam satu file tanpa library.
- **Simpan di localStorage** → `save()` dipanggil setiap ada perubahan, dan `load()` membaca serta memvalidasi data saat halaman dibuka.
- **Tambah** → form `#new-todo`.
- **Edit** → klik dua kali atau ikon pensil. **Enter** menyimpan, **Esc** membatalkan, dan teks kosong menghapus tugas (`finishEdit()`).
- **Hapus** → tombol hapus per tugas, plus `#clear-done` untuk menghapus semua tugas yang selesai.
- **Centang selesai** → checkbox di setiap tugas.
- **Filter semua/aktif/selesai** → tombol filter dan `visibleTodos()`, dengan penghitung tugas tersisa di `#counter`.

**Catatan teknis**
- Akses `localStorage` dibungkus `try/catch` karena bisa gagal, misalnya di mode privat atau saat penyimpanan penuh.
- Event delegation di elemen `<ul>`, jadi listener tidak menumpuk setiap kali daftar dirender ulang.

Berikut kalkulator dalam satu file HTML. Ekspresinya dihitung dengan parser sederhana, jadi sama sekali tidak memakai `eval()`.

```html
<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kalkulator</title>
  <style>
    :root {
      --bg: #0f172a; --body: #1e293b; --key: #334155; --key-hover: #475569;
      --text: #f8fafc; --muted: #94a3b8; --op: #f59e0b; --op-hover: #fbbf24; --fn: #64748b;
    }
    *, *::before, *::after { box-sizing: border-box; }
    body {
      margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 1rem;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      background: radial-gradient(circle at top, #1e3a8a 0%, var(--bg) 60%); color: var(--text);
    }
    .calculator {
      width: min(100%, 360px); padding: 1.25rem; border-radius: 28px;
      background: var(--body); box-shadow: 0 30px 60px rgba(0, 0, 0, .45);
    }
    .display {
      min-height: 130px; display: flex; flex-direction: column; justify-content: flex-end; align-items: flex-end;
      padding: .5rem .75rem 1rem; overflow: hidden;
    }
    .expression { color: var(--muted); font-size: 1.1rem; min-height: 1.6em; word-break: break-all; text-align: right; }
    .result { font-size: clamp(2rem, 11vw, 3rem); font-weight: 300; line-height: 1.1; word-break: break-all; text-align: right; }
    .result.error { font-size: 1.4rem; color: #fca5a5; }
    .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: .75rem; }
    .key {
      aspect-ratio: 1; border: 0; border-radius: 50%; cursor: pointer;
      background: var(--key); color: var(--text); font: inherit; font-size: 1.5rem;
      transition: background-color .15s, transform .08s;
    }
    .key:hover { background: var(--key-hover); }
    .key:active, .key.pressed { transform: scale(.94); }
    .key.fn { background: var(--fn); font-size: 1.2rem; }
    .key.op { background: var(--op); color: #111827; font-weight: 600; }
    .key.op:hover { background: var(--op-hover); }
    .key:focus-visible { outline: 3px solid #93c5fd; outline-offset: 2px; }
    .hint { margin-top: 1rem; text-align: center; color: var(--muted); font-size: .8rem; }
  </style>
</head>
<body>
  <main class="calculator" aria-label="Kalkulator">
    <div class="display">
      <div class="expression" id="expression" aria-label="Ekspresi"></div>
      <output class="result" id="result" aria-live="polite">0</output>
    </div>
    <div class="keys">
      <button class="key fn" type="button" data-action="clear" aria-label="Hapus semua">AC</button>
      <button class="key fn" type="button" data-action="backspace" aria-label="Hapus satu">⌫</button>
      <button class="key fn" type="button" data-action="percent" aria-label="Persen">%</button>
      <button class="key op" type="button" data-op="÷" aria-label="Bagi">÷</button>
      <button class="key" type="button" data-digit="7">7</button>
      <button class="key" type="button" data-digit="8">8</button>
      <button class="key" type="button" data-digit="9">9</button>
      <button class="key op" type="button" data-op="×" aria-label="Kali">×</button>
      <button class="key" type="button" data-digit="4">4</button>
      <button class="key" type="button" data-digit="5">5</button>
      <button class="key" type="button" data-digit="6">6</button>
      <button class="key op" type="button" data-op="−" aria-label="Kurang">−</button>
      <button class="key" type="button" data-digit="1">1</button>
      <button class="key" type="button" data-digit="2">2</button>
      <button class="key" type="button" data-digit="3">3</button>
      <button class="key op" type="button" data-op="+" aria-label="Tambah">+</button>
      <button class="key fn" type="button" data-action="negate" aria-label="Ubah tanda">±</button>
      <button class="key" type="button" data-digit="0">0</button>
      <button class="key" type="button" data-action="decimal" aria-label="Koma desimal">,</button>
      <button class="key op" type="button" data-action="equals" aria-label="Sama dengan">=</button>
    </div>
    <p class="hint">Bisa pakai keyboard: angka, + − * /, Enter, Backspace, Esc</p>
  </main>

  <script>
    const OPERATORS = ['+', '−', '×', '÷'];
    const MAX_DIGITS = 15;
    const expressionEl = document.getElementById('expression');
    const resultEl = document.getElementById('result');

    // Ekspresi disimpan sebagai token: angka (string, desimal pakai titik) dan operator.
    let tokens = [];
    let justEvaluated = false;
    let errorMessage = '';

    const isOperator = (t) => OPERATORS.includes(t);
    const last = () => tokens[tokens.length - 1];
    const setLast = (value) => { tokens[tokens.length - 1] = value; };

    function evaluate(list) {
      const t = [...list];
      if (isOperator(t[t.length - 1])) t.pop();
      if (t.length === 0) return 0;
      // Kali dan bagi dikerjakan dulu, hasilnya dijumlahkan di akhir.
      const terms = [parseFloat(t[0])];
      for (let i = 1; i < t.length; i += 2) {
        const op = t[i];
        const num = parseFloat(t[i + 1]);
        if (op === '×') terms.push(terms.pop() * num);
        else if (op === '÷') {
          if (num === 0) throw new Error('Tidak bisa dibagi nol');
          terms.push(terms.pop() / num);
        } else terms.push(op === '−' ? -num : num);
      }
      const total = terms.reduce((a, b) => a + b, 0);
      if (!Number.isFinite(total)) throw new Error('Hasil terlalu besar');
      return parseFloat(total.toPrecision(12)); // buang noise floating point, misal 0,1 + 0,2
    }

    function formatNumber(tok) {
      if (/e/i.test(tok)) return tok.replace('.', ',');
      const negative = tok.startsWith('-');
      const [intPart, fracPart] = tok.replace('-', '').split('.');
      const grouped = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
      return (negative ? '−' : '') + grouped + (fracPart !== undefined ? ',' + fracPart : '');
    }

    function render() {
      expressionEl.textContent = tokens.map((t) => (isOperator(t) ? ` ${t} ` : formatNumber(t))).join('');
      resultEl.classList.toggle('error', Boolean(errorMessage));
      if (errorMessage) {
        resultEl.textContent = errorMessage;
        return;
      }
      try {
        resultEl.textContent = formatNumber(String(evaluate(tokens)));
      } catch (e) {
        resultEl.textContent = '…';
      }
    }

    function startFresh() {
      tokens = [];
      justEvaluated = false;
      errorMessage = '';
    }

    function inputDigit(d) {
      if (justEvaluated || errorMessage) startFresh();
      const tok = last();
      if (tok === undefined || isOperator(tok)) tokens.push(d);
      else if (tok.replace(/[-.]/g, '').length >= MAX_DIGITS) return;
      else if (tok === '0') setLast(d);
      else if (tok === '-0') setLast('-' + d);
      else setLast(tok + d);
    }

    function inputDecimal() {
      if (justEvaluated || errorMessage) startFresh();
      const tok = last();
      if (tok === undefined || isOperator(tok)) tokens.push('0.');
      else if (!tok.includes('.') && !/e/i.test(tok)) setLast(tok + '.');
    }

    function inputOperator(op) {
      if (errorMessage) return;
      justEvaluated = false;
      const tok = last();
      if (tok === undefined) tokens.push('0', op);
      else if (isOperator(tok)) setLast(op);
      else tokens.push(op);
    }

    function applyToLastNumber(fn) {
      if (errorMessage) return;
      const tok = last();
      if (tok === undefined || isOperator(tok)) return;
      justEvaluated = false;
      setLast(fn(tok));
    }

    function backspace() {
      if (errorMessage || justEvaluated) return startFresh();
      const tok = last();
      if (tok === undefined) return;
      if (isOperator(tok) || tok.length === 1 || /^-\d$/.test(tok)) tokens.pop();
      else setLast(tok.slice(0, -1));
    }

    function equals() {
      if (errorMessage || tokens.length === 0) return;
      try {
        tokens = [String(evaluate(tokens))];
        justEvaluated = true;
      } catch (e) {
        errorMessage = e.message;
      }
    }

    function handle(action, value) {
      switch (action) {
        case 'digit': inputDigit(value); break;
        case 'decimal': inputDecimal(); break;
        case 'op': inputOperator(value); break;
        case 'clear': startFresh(); break;
        case 'backspace': backspace(); break;
        case 'negate': applyToLastNumber((t) => (t.startsWith('-') ? t.slice(1) : '-' + t)); break;
        case 'percent': applyToLastNumber((t) => String(parseFloat((parseFloat(t) / 100).toPrecision(12)))); break;
        case 'equals': equals(); break;
      }
      render();
    }

    document.querySelector('.keys').addEventListener('click', (e) => {
      const key = e.target.closest('.key');
      if (!key) return;
      if (key.dataset.digit) handle('digit', key.dataset.digit);
      else if (key.dataset.op) handle('op', key.dataset.op);
      else handle(key.dataset.action);
    });

    const KEYMAP = {
      '+': ['op', '+'], '-': ['op', '−'], '*': ['op', '×'], 'x': ['op', '×'], '/': ['op', '÷'],
      '.': ['decimal'], ',': ['decimal'], '%': ['percent'],
      'Enter': ['equals'], '=': ['equals'], 'Backspace': ['backspace'], 'Escape': ['clear'], 'Delete': ['clear']
    };

    document.addEventListener('keydown', (e) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      let mapping = /^\d$/.test(e.key) ? ['digit', e.key] : KEYMAP[e.key];
      if (!mapping) return;
      e.preventDefault();
      handle(...mapping);
      const selector = mapping[0] === 'digit' ? `[data-digit="${e.key}"]`
        : mapping[0] === 'op' ? `[data-op="${mapping[1]}"]`
        : `[data-action="${mapping[0]}"]`;
      const button = document.querySelector(selector);
      if (button) {
        button.classList.add('pressed');
        setTimeout(() => button.classList.remove('pressed'), 100);
      }
    });

    render();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Elegan** → layar dua baris (ekspresi dan hasil) dengan tombol yang beranimasi saat ditekan.
- **Bisa dipakai dengan keyboard** → `KEYMAP` memetakan angka, `+ - * /`, `.` atau `,` untuk desimal, `%`, **Enter** atau `=`, **Backspace**, dan **Esc**. Tombol di layar ikut beranimasi saat tombol keyboard ditekan.
- **Tanpa `eval()`** → input disimpan sebagai token, lalu `evaluate()` mengerjakan × dan ÷ lebih dulu sebelum penjumlahan, sehingga `2 + 3 × 4 = 14`.

**Detail**
- Hasil dibulatkan dengan `toPrecision(12)`, jadi `0,1 + 0,2` tampil sebagai `0,3`. Angka memakai format Indonesia: titik untuk ribuan dan koma untuk desimal.
- Pembagian dengan nol menampilkan pesan error, dan input berikutnya memulai perhitungan baru.

**Kenapa tidak memakai `eval()`?** `eval()` menjalankan string sebagai kode JavaScript, sehingga membuka celah eksekusi kode jika isinya bisa dipengaruhi pengguna. Parser sendiri juga memberi kontrol penuh atas urutan operasi dan pesan error.

