      { id: 'TRX-1039', customer: 'Yoga Prasetyo', date: '2026-12-13', status: 'Lunas', total: 890000 }
    ];

    const rupiah = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0, maximumFractionDigits: 0 });
    const compact = new Intl.NumberFormat('id-ID', { notation: 'compact', maximumFractionDigits: 1 });
    const number = new Intl.NumberFormat('id-ID');
    const dateFmt = new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });

    // ----- Kartu statistik: bulan terakhir dibanding bulan sebelumnya -----
    function renderStats() {
      const i = REVENUE.length - 1;
      const aov = (k) => REVENUE[k] / ORDERS[k];
      const cards = [
        { label: 'Pendapatan bulan ini', value: rupiah.format(REVENUE[i]), now: REVENUE[i], prev: REVENUE[i - 1] },
        { label: 'Jumlah pesanan', value: number.format(ORDERS[i]), now: ORDERS[i], prev: ORDERS[i - 1] },
        { label: 'Rata-rata nilai pesanan', value: rupiah.format(aov(i)), now: aov(i), prev: aov(i - 1) },
        { label: 'Pelanggan baru', value: number.format(NEW_CUSTOMERS[i]), now: NEW_CUSTOMERS[i], prev: NEW_CUSTOMERS[i - 1] }
      ];
      document.getElementById('stats').replaceChildren(...cards.map((c) => {
        const change = ((c.now - c.prev) / c.prev) * 100;
        const card = document.createElement('article');
        card.className = 'card';
        const label = Object.assign(document.createElement('p'), { className: 'stat-label', textContent: c.label });
        const value = Object.assign(document.createElement('p'), { className: 'stat-value', textContent: c.value });
        const delta = Object.assign(document.createElement('p'), {
          className: `delta ${change >= 0 ? 'up' : 'down'}`,
          textContent: `${change >= 0 ? '▲' : '▼'} ${Math.abs(change).toLocaleString('id-ID', { maximumFractionDigits: 1 })}% dari bulan lalu`
        });
        card.append(label, value, delta);
        return card;
      }));
    }

    // ----- Grafik batang SVG -----
    function renderChart() {
      const svg = document.getElementById('chart');
      const tooltip = document.getElementById('chart-tooltip');
      const NS = 'http://www.w3.org/2000/svg';
      const W = 720, H = 300, pad = { top: 16, right: 12, bottom: 32, left: 64 };
      const innerW = W - pad.left - pad.right;
      const innerH = H - pad.top - pad.bottom;
      const max = Math.ceil(Math.max(...REVENUE) / 1e8) * 1e8;
      const y = (v) => pad.top + innerH - (v / max) * innerH;
      const slot = innerW / REVENUE.length;
      const make = (tag, attrs) => {
        const node = document.createElementNS(NS, tag);
        for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
        return node;
      };
      svg.replaceChildren();

      for (let v = 0; v <= max; v += 1e8) {
        svg.append(make('line', { class: 'grid', x1: pad.left, x2: W - pad.right, y1: y(v), y2: y(v) }));
        const label = make('text', { x: pad.left - 10, y: y(v) + 4, 'text-anchor': 'end' });
        label.textContent = v === 0 ? '0' : compact.format(v);
        svg.append(label);
      }

      REVENUE.forEach((v, i) => {
        const barW = slot * 0.6;
        const x = pad.left + i * slot + (slot - barW) / 2;
        const detail = `${MONTHS[i]}: ${rupiah.format(v)} dari ${number.format(ORDERS[i])} pesanan`;
        const bar = make('rect', { class: 'bar', x, y: y(v), width: barW, height: y(0) - y(v), rx: 4, tabindex: 0, 'aria-label': detail });
        const show = () => { tooltip.textContent = detail; };
        bar.addEventListener('mouseenter', show);
        bar.addEventListener('focus', show);
        svg.append(bar);
        const label = make('text', { x: x + barW / 2, y: H - 10, 'text-anchor': 'middle' });
        label.textContent = MONTHS[i];
        svg.append(label);
      });
    }

    // ----- Tabel dengan pencarian dan pengurutan -----
    const tbody = document.getElementById('tbody');
    const searchInput = document.getElementById('search');
    const headers = document.querySelectorAll('th[data-key]');
    let sort = { key: 'date', dir: 'descending' };

    function renderTable() {
      const q = searchInput.value.trim().toLowerCase();
      const rows = TRANSACTIONS
        .filter((t) => !q || t.id.toLowerCase().includes(q) || t.customer.toLowerCase().includes(q))
        .sort((a, b) => {
          const A = a[sort.key], B = b[sort.key];
          const cmp = typeof A === 'number' ? A - B : String(A).localeCompare(String(B), 'id');
          return sort.dir === 'ascending' ? cmp : -cmp;
        });

      if (rows.length === 0) {
        const tr = document.createElement('tr');
        tr.className = 'empty-row';
        const td = Object.assign(document.createElement('td'), { colSpan: 5, textContent: `Tidak ada transaksi yang cocok dengan "${searchInput.value}".` });
        tr.append(td);
        tbody.replaceChildren(tr);
        return;
      }

      tbody.replaceChildren(...rows.map((t) => {
        const tr = document.createElement('tr');
        const status = Object.assign(document.createElement('span'), {
          className: `status ${t.status.toLowerCase()}`, textContent: t.status
        });
        const cells = [
          t.id,
          t.customer,
          dateFmt.format(new Date(`${t.date}T00:00:00`)),
          status,
          rupiah.format(t.total)
        ];
        cells.forEach((content, i) => {
          const td = document.createElement('td');
          if (i === 4) td.className = 'num';
          td.append(content);
          tr.append(td);
        });
        return tr;
      }));
    }

    headers.forEach((th) => {
      th.querySelector('button').addEventListener('click', () => {
        const key = th.dataset.key;
        sort = { key, dir: sort.key === key && sort.dir === 'ascending' ? 'descending' : 'ascending' };
        headers.forEach((h) => h.setAttribute('aria-sort', h.dataset.key === key ? sort.dir : 'none'));
        renderTable();
      });
    });
    searchInput.addEventListener('input', renderTable);

    // ----- Sidebar mobile -----
    const sidebar = document.getElementById('sidebar');
    const menuBtn = document.getElementById('menu-btn');
    function setSidebar(open) {
      sidebar.classList.toggle('open', open);
      menuBtn.setAttribute('aria-expanded', String(open));
    }
    menuBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      setSidebar(!sidebar.classList.contains('open'));
    });
    document.addEventListener('click', (e) => {
      if (sidebar.classList.contains('open') && !sidebar.contains(e.target)) setSidebar(false);
    });
    document.addEventListener('keydown', (e) => { if (e.key === 'Escape') setSidebar(false); });

    renderStats();
    renderChart();
    renderTable();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Sidebar** → navigasi samping. Di layar kecil berubah menjadi menu geser (`setSidebar()`) yang bisa ditutup dengan klik di luar atau **Esc**.
- **Kartu statistik** → `renderStats()` membuat empat kartu yang membandingkan bulan terakhir dengan bulan sebelumnya, lengkap dengan persentase naik atau turun.
- **Grafik pendapatan bulanan** → `renderChart()` menggambar grafik batang 12 bulan dengan SVG. Setiap batang bisa difokus dengan keyboard untuk menampilkan detail.
- **Tabel transaksi yang bisa dicari dan diurutkan** → `renderTable()` menyaring berdasarkan ID atau nama pelanggan dari `#search`. Klik judul kolom mengurutkan data dan memperbarui `aria-sort`.
- **Tanpa library eksternal** → grafik dan tabel dibuat dengan HTML, CSS, SVG, dan JavaScript biasa.

**Cara menyesuaikan**
- Ganti array `REVENUE`, `ORDERS`, `NEW_CUSTOMERS`, dan `TRANSACTIONS` dengan data dari API, lalu panggil ulang `renderStats()`, `renderChart()`, dan `renderTable()`.

Berikut kuis pengetahuan umum Indonesia dalam satu file HTML: 10 soal, timer 20 detik per soal, skor, dan pembahasan di akhir.

```html
<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kuis Pengetahuan Indonesia</title>
  <style>
    :root {
      --bg: #fef3c7; --card: #ffffff; --text: #1f2937; --muted: #6b7280; --border: #e5e7eb;
      --brand: #dc2626; --brand-dark: #b91c1c; --correct: #16a34a; --wrong: #dc2626;
    }
    *, *::before, *::after { box-sizing: border-box; }
    body {
      margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 1rem;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      background: linear-gradient(160deg, #fee2e2, var(--bg)); color: var(--text);
    }
    .card { width: min(100%, 640px); background: var(--card); border-radius: 20px; padding: clamp(1.25rem, 4vw, 2.25rem); box-shadow: 0 25px 50px rgba(0, 0, 0, .08); }
    h1 { margin: 0 0 .5rem; font-size: clamp(1.5rem, 4vw, 2rem); }
    p { line-height: 1.6; }
    .muted { color: var(--muted); }
    :focus-visible { outline: 3px solid #fca5a5; outline-offset: 2px; }
    .btn {
      padding: .85rem 1.5rem; border: 0; border-radius: 12px; cursor: pointer;
      background: var(--brand); color: #fff; font: inherit; font-weight: 700;
    }
    .btn:hover { background: var(--brand-dark); }
    .btn-secondary { background: #f3f4f6; color: var(--text); }
    .btn-secondary:hover { background: #e5e7eb; }

    .meta { display: flex; justify-content: space-between; align-items: center; gap: 1rem; color: var(--muted); font-weight: 600; }
    .timer { display: inline-flex; align-items: center; gap: .4rem; font-variant-numeric: tabular-nums; }
    .timer.warning { color: var(--wrong); }
    .progress { height: 6px; background: var(--border); border-radius: 999px; margin: .75rem 0 1.5rem; overflow: hidden; }
    .progress div { height: 100%; background: var(--brand); transition: width .3s; }
    .question { font-size: 1.25rem; font-weight: 700; margin: 0 0 1.25rem; }
    .options { display: grid; gap: .75rem; }
    .option {
      text-align: left; padding: .9rem 1rem; border-radius: 12px; cursor: pointer;
      border: 2px solid var(--border); background: #fff; color: var(--text); font: inherit;
    }
    .option:hover:not(:disabled) { border-color: var(--brand); }
    .option:disabled { cursor: default; }
    .option.correct { border-color: var(--correct); background: #f0fdf4; }
    .option.wrong { border-color: var(--wrong); background: #fef2f2; }
    .feedback { min-height: 1.6em; margin: 1rem 0; font-weight: 600; }
    .actions { display: flex; justify-content: flex-end; }

    .score { font-size: 3rem; font-weight: 800; margin: .5rem 0; color: var(--brand); }
    .review { list-style: none; padding: 0; margin: 1.5rem 0; display: grid; gap: .75rem; }
    .review li { padding: 1rem; border-radius: 12px; border-left: 5px solid var(--correct); background: #f9fafb; }
    .review li.miss { border-left-color: var(--wrong); }
    .review strong { display: block; margin-bottom: .25rem; }
    .review p { margin: .25rem 0 0; font-size: .95rem; }
    [hidden] { display: none !important; }
    @media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
  </style>
</head>
<body>
  <main class="card">
    <section id="start-screen">
      <h1>Kuis Pengetahuan Indonesia</h1>
      <p class="muted">10 soal pilihan ganda tentang sejarah, geografi, dan budaya Indonesia. Setiap soal punya waktu 20 detik. Pembahasan lengkap muncul di akhir.</p>
      <button class="btn" id="start-btn" type="button">Mulai Kuis</button>
    </section>

    <section id="quiz-screen" hidden>
      <div class="meta">
        <span id="counter"></span>
        <span class="timer" id="timer" aria-live="off"></span>
      </div>
      <div class="progress" aria-hidden="true"><div id="progress-bar"></div></div>
      <h2 class="question" id="question"></h2>
      <div class="options" id="options"></div>
      <p class="feedback" id="feedback" role="status"></p>
      <div class="actions">
        <button class="btn" id="next-btn" type="button" hidden>Soal berikutnya</button>
      </div>
    </section>

    <section id="result-screen" hidden>
      <h1>Hasil Kuis</h1>
      <p class="score" id="score"></p>
      <p class="muted" id="verdict"></p>
      <ol class="review" id="review"></ol>
      <button class="btn" id="restart-btn" type="button">Main Lagi</button>
    </section>
  </main>

  <script>
    const QUESTIONS = [
      { q: 'Teks Proklamasi Kemerdekaan Indonesia dibacakan pada tanggal…', options: ['17 Agustus 1945', '18 Agustus 1945', '1 Juni 1945', '28 Oktober 1928'], answer: 0, explain: 'Proklamasi dibacakan Soekarno didampingi Mohammad Hatta pada 17 Agustus 1945 di Jalan Pegangsaan Timur 56, Jakarta.' },
      { q: 'Bunyi sila ketiga Pancasila adalah…', options: ['Kemanusiaan yang adil dan beradab', 'Persatuan Indonesia', 'Keadilan sosial bagi seluruh rakyat Indonesia', 'Ketuhanan Yang Maha Esa'], answer: 1, explain: 'Sila ketiga adalah "Persatuan Indonesia", dilambangkan dengan pohon beringin.' },
      { q: 'Danau vulkanik terbesar di Indonesia adalah…', options: ['Danau Singkarak', 'Danau Poso', 'Danau Toba', 'Danau Maninjau'], answer: 2, explain: 'Danau Toba di Sumatra Utara terbentuk dari letusan supervulkan dan merupakan danau terbesar di Indonesia.' },
      { q: 'Lagu kebangsaan "Indonesia Raya" diciptakan oleh…', options: ['Ismail Marzuki', 'C. Simanjuntak', 'Kusbini', 'W.R. Supratman'], answer: 3, explain: 'Wage Rudolf Supratman menciptakan "Indonesia Raya" dan memperdengarkannya pertama kali pada Kongres Pemuda II tahun 1928.' },
      { q: 'Semboyan "Bhinneka Tunggal Ika" berasal dari kitab…', options: ['Negarakertagama', 'Sutasoma', 'Arjunawiwaha', 'Pararaton'], answer: 1, explain: 'Semboyan ini berasal dari Kakawin Sutasoma karya Mpu Tantular pada masa Majapahit.' },
      { q: 'Habitat asli komodo berada di provinsi…', options: ['Nusa Tenggara Timur', 'Nusa Tenggara Barat', 'Bali', 'Sulawesi Selatan'], answer: 0, explain: 'Komodo hidup di Pulau Komodo, Rinca, dan sekitarnya yang termasuk Provinsi Nusa Tenggara Timur.' },
      { q: 'Candi Borobudur terletak di provinsi…', options: ['DI Yogyakarta', 'Jawa Timur', 'Jawa Tengah', 'Jawa Barat'], answer: 2, explain: 'Borobudur berada di Kabupaten Magelang, Jawa Tengah, meskipun sering dikunjungi lewat Yogyakarta.' },
      { q: 'Selat yang memisahkan Pulau Jawa dan Pulau Sumatra adalah…', options: ['Selat Bali', 'Selat Makassar', 'Selat Malaka', 'Selat Sunda'], answer: 3, explain: 'Selat Sunda memisahkan Jawa dan Sumatra. Gunung Anak Krakatau berada di selat ini.' },
      { q: 'Gunung tertinggi di Indonesia adalah…', options: ['Puncak Jaya', 'Gunung Kerinci', 'Gunung Semeru', 'Gunung Rinjani'], answer: 0, explain: 'Puncak Jaya (Carstensz Pyramid) di Papua memiliki tinggi sekitar 4.884 meter di atas permukaan laut.' },
      { q: 'Peristiwa Sumpah Pemuda terjadi pada tanggal…', options: ['20 Mei 1908', '28 Oktober 1928', '10 November 1945', '2 Mei 1889'], answer: 1, explain: 'Sumpah Pemuda diikrarkan pada Kongres Pemuda II, 28 Oktober 1928.' }
    ];
    const SECONDS_PER_QUESTION = 20;
    const LETTERS = ['A', 'B', 'C', 'D'];

    const $ = (id) => document.getElementById(id);
    const screens = { start: $('start-screen'), quiz: $('quiz-screen'), result: $('result-screen') };
    let order = [];
    let current = 0;
    let answers = [];
    let timerId = null;
    let deadline = 0;

    function show(name) {
      Object.entries(screens).forEach(([key, el]) => { el.hidden = key !== name; });
    }

    function shuffle(array) {
      const a = [...array];
      for (let i = a.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [a[i], a[j]] = [a[j], a[i]];
      }
      return a;
    }

    function startQuiz() {
      order = shuffle(QUESTIONS.map((_, i) => i));
      answers = [];
      current = 0;
      show('quiz');
      renderQuestion();
    }

    function renderQuestion() {
      const item = QUESTIONS[order[current]];
      $('counter').textContent = `Soal ${current + 1} dari ${order.length}`;
      $('progress-bar').style.width = `${(current / order.length) * 100}%`;
      $('question').textContent = item.q;
      $('feedback').textContent = '';
      $('next-btn').hidden = true;
      $('options').replaceChildren(...item.options.map((text, i) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'option';
        button.textContent = `${LETTERS[i]}. ${text}`;
        button.addEventListener('click', () => choose(i));
        return button;
      }));
      $('question').setAttribute('tabindex', '-1');
      $('question').focus();
      startTimer();
    }

    function startTimer() {
      clearInterval(timerId);
      deadline = Date.now() + SECONDS_PER_QUESTION * 1000;
      tick();
      timerId = setInterval(tick, 250);
    }

    function tick() {
      const left = Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
      $('timer').textContent = `⏱ ${left} detik`;
      $('timer').classList.toggle('warning', left <= 5);
      if (left === 0) choose(null);
    }

    function choose(index) {
      if (answers.length > current) return; // soal ini sudah dijawab
      clearInterval(timerId);
      const item = QUESTIONS[order[current]];
      answers.push(index);
      const buttons = $('options').querySelectorAll('.option');
      buttons.forEach((b, i) => {
        b.disabled = true;
        if (i === item.answer) b.classList.add('correct');
        else if (i === index) b.classList.add('wrong');
      });
      const correctText = `${LETTERS[item.answer]}. ${item.options[item.answer]}`;
      $('feedback').textContent = index === null
        ? `Waktu habis! Jawaban yang benar: ${correctText}`
        : index === item.answer ? 'Benar!' : `Kurang tepat. Jawaban yang benar: ${correctText}`;
      const nextBtn = $('next-btn');
      nextBtn.textContent = current === order.length - 1 ? 'Lihat hasil' : 'Soal berikutnya';
      nextBtn.hidden = false;
      nextBtn.focus();
    }

    function next() {
      current++;
      if (current < order.length) renderQuestion();
      else showResult();
    }

    function showResult() {
      const correct = answers.filter((a, i) => a === QUESTIONS[order[i]].answer).length;
      $('score').textContent = `${correct} / ${order.length}`;
      $('verdict').textContent = correct === order.length ? 'Sempurna! Pengetahuanmu luar biasa.'
        : correct >= 7 ? 'Bagus sekali! Tinggal sedikit lagi menuju sempurna.'
        : correct >= 4 ? 'Lumayan! Baca pembahasan di bawah untuk belajar lagi.'
        : 'Jangan menyerah! Pelajari pembahasannya lalu coba lagi.';
      $('review').replaceChildren(...order.map((qi, i) => {
        const item = QUESTIONS[qi];
        const chosen = answers[i];
        const li = document.createElement('li');
        if (chosen !== item.answer) li.classList.add('miss');
        const title = document.createElement('strong');
        title.textContent = item.q;
        const yours = document.createElement('p');
        yours.textContent = chosen === null ? 'Jawabanmu: (tidak dijawab)' : `Jawabanmu: ${item.options[chosen]}`;
        const explain = document.createElement('p');
        explain.textContent = `Pembahasan: ${item.explain}`;
        li.append(title, yours, explain);
        return li;
      }));
      show('result');
      $('score').setAttribute('tabindex', '-1');
      $('score').focus();
    }

    $('start-btn').addEventListener('click', startQuiz);
    $('next-btn').addEventListener('click', next);
    $('restart-btn').addEventListener('click', startQuiz);
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Pengetahuan umum tentang Indonesia** → array `QUESTIONS` berisi soal seputar Indonesia, masing-masing dengan pembahasan.
- **10 soal pilihan ganda** → setiap soal punya empat opsi (A–D), dan urutan soal diacak dengan `shuffle()` (Fisher-Yates) setiap permainan.
- **Timer tiap soal** → `startTimer()` menghitung mundur `SECONDS_PER_QUESTION` detik dari `Date.now()`, sehingga tetap akurat walaupun tab sempat tidak aktif. Saat waktu habis, soal dianggap tidak dijawab dan jawaban yang benar ditampilkan.
- **Skor** → bertambah setiap jawaban benar dan ditampilkan oleh `showResult()`.
- **Pembahasan di akhir** → halaman hasil berisi komentar sesuai nilai dan pembahasan setiap soal di `#review`.

**Cara menyesuaikan**
- Tambah atau ubah soal di `QUESTIONS`. Properti `answer` adalah indeks opsi yang benar, dimulai dari 0.

Berikut game Snake dengan canvas dalam satu file HTML. Game ini bisa dimainkan dengan keyboard, swipe, atau tombol arah di layar sentuh.

```html
