    }
    .game { width: min(100%, 480px); }
    .hud { display: flex; justify-content: space-between; margin-bottom: .75rem; font-weight: 700; font-variant-numeric: tabular-nums; }
    .hud span { color: var(--muted); font-weight: 500; }
    .board-wrap { position: relative; }
    canvas { display: block; width: 100%; aspect-ratio: 1; border-radius: 12px; touch-action: none; }
    .overlay {
      position: absolute; inset: 0; display: grid; place-items: center; text-align: center; padding: 1.5rem;
      border-radius: 12px; background: rgba(5, 46, 22, .78);
