    .pad { display: none; grid-template-columns: repeat(3, 64px); gap: .5rem; justify-content: center; margin-top: 1rem; }
    .pad button {
      height: 56px; border: 0; border-radius: 14px; background: var(--panel); color: var(--text);
      font-size: 1.4rem; cursor: pointer; touch-action: manipulation;
    }
    .pad .up { grid-column: 2; }
    .pad .left { grid-column: 1; grid-row: 2; }
    .pad .down { grid-column: 2; grid-row: 2; }
    .pad .right { grid-column: 3; grid-row: 2; }
    .help { text-align: center; color: var(--muted); font-size: .85rem; margin-top: .75rem; }
    @media (pointer: coarse) { .pad { display: grid; } }
    [hidden] { display: none !important; }
  </style>
</head>
<body>
  <main class="game">
    <div class="hud">
      <div>Skor <span id="score">0</span></div>
      <div>Tertinggi <span id="best">0</span></div>
    </div>
    <div class="board-wrap">
      <canvas id="board" aria-label="Papan permainan Snake"></canvas>
      <div class="overlay" id="overlay">
        <div>
          <h1 id="overlay-title">Snake</h1>
          <p id="overlay-text">Makan buah, jangan tabrak dinding atau badan sendiri.</p>
          <button class="btn" id="play-btn" type="button">Mulai</button>
        </div>
      </div>
    </div>
    <div class="pad" aria-label="Kontrol arah">
      <button class="up" type="button" data-dir="up" aria-label="Atas">▲</button>
      <button class="left" type="button" data-dir="left" aria-label="Kiri">◀</button>
      <button class="down" type="button" data-dir="down" aria-label="Bawah">▼</button>
      <button class="right" type="button" data-dir="right" aria-label="Kanan">▶</button>
    </div>
    <p class="help">Panah / WASD untuk bergerak · Spasi untuk jeda · Di HP: geser layar atau pakai tombol</p>
  </main>

  <script>
    const GRID = 20;
    const START_SPEED = 140;  // ms per langkah
    const MIN_SPEED = 65;
    const BEST_KEY = 'snake-best';
    const DIRS = { up: { x: 0, y: -1 }, down: { x: 0, y: 1 }, left: { x: -1, y: 0 }, right: { x: 1, y: 0 } };

    const canvas = document.getElementById('board');
    const ctx = canvas.getContext('2d');
    const scoreEl = document.getElementById('score');
    const bestEl = document.getElementById('best');
    const overlay = document.getElementById('overlay');
    const overlayTitle = document.getElementById('overlay-title');
    const overlayText = document.getElementById('overlay-text');
    const playBtn = document.getElementById('play-btn');

    let snake, dir, queue, food, score, speed, state, lastStep, cell;
    let best = 0;
    try { best = Number(localStorage.getItem(BEST_KEY)) || 0; } catch (e) { /* abaikan */ }
    bestEl.textContent = best;

    function reset() {
      snake = [{ x: 8, y: 10 }, { x: 7, y: 10 }, { x: 6, y: 10 }];
      dir = DIRS.right;
      queue = [];
      score = 0;
      speed = START_SPEED;
      scoreEl.textContent = 0;
      food = spawnFood();
    }

    function spawnFood() {
      const free = [];
      for (let y = 0; y < GRID; y++) {
        for (let x = 0; x < GRID; x++) {
          if (!snake.some((s) => s.x === x && s.y === y)) free.push({ x, y });
        }
      }
      return free.length ? free[Math.floor(Math.random() * free.length)] : null;
    }

    function turn(name) {
      const next = DIRS[name];
      const lastDir = queue.length ? queue[queue.length - 1] : dir;
      // Abaikan belokan 180° dan tombol yang sama; simpan maksimal 2 belokan supaya tetap responsif.
      if (next.x === -lastDir.x && next.y === -lastDir.y) return;
      if (next === lastDir || queue.length >= 2) return;
      queue.push(next);
    }

    function step() {
      if (queue.length) dir = queue.shift();
      const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };
      const eats = food && head.x === food.x && head.y === food.y;
      const body = eats ? snake : snake.slice(0, -1); // ekor akan bergeser kalau tidak makan
      const hitsWall = head.x < 0 || head.y < 0 || head.x >= GRID || head.y >= GRID;
      if (hitsWall || body.some((s) => s.x === head.x && s.y === head.y)) return gameOver();

      snake.unshift(head);
      if (eats) {
        score++;
        scoreEl.textContent = score;
        speed = Math.max(MIN_SPEED, speed - 3);
        food = spawnFood();
        if (!food) return gameOver(true);
      } else {
        snake.pop();
      }
    }

    function loop(time) {
      if (state !== 'running') return;
      if (time - lastStep >= speed) {
        lastStep = time;
        step();
        draw();
      }
      requestAnimationFrame(loop);
    }

    function start() {
      if (state === 'over' || state === undefined) reset();
      state = 'running';
      overlay.hidden = true;
      lastStep = performance.now();
      requestAnimationFrame(loop);
    }

    function pause() {
      if (state !== 'running') return;
      state = 'paused';
      showOverlay('Jeda', 'Tekan spasi atau tombol di bawah untuk lanjut.', 'Lanjut');
    }

    function gameOver(won = false) {
      state = 'over';
      if (score > best) {
        best = score;
        bestEl.textContent = best;
        try { localStorage.setItem(BEST_KEY, String(best)); } catch (e) { /* abaikan */ }
      }
      draw();
      showOverlay(won ? 'Kamu menang!' : 'Game over', `Skor kamu ${score}. Rekor: ${best}.`, 'Main lagi');
    }

    function showOverlay(title, text, label) {
      overlayTitle.textContent = title;
      overlayText.textContent = text;
      playBtn.textContent = label;
      overlay.hidden = false;
      playBtn.focus();
    }

    function roundRect(x, y, w, h, r) {
      ctx.beginPath();
      if (ctx.roundRect) ctx.roundRect(x, y, w, h, r);
      else ctx.rect(x, y, w, h);
      ctx.fill();
    }

    function draw() {
      const size = cell * GRID;
      for (let y = 0; y < GRID; y++) {
        for (let x = 0; x < GRID; x++) {
          ctx.fillStyle = (x + y) % 2 ? '#166534' : '#15803d';
          ctx.fillRect(x * cell, y * cell, cell, cell);
        }
      }
      if (food) {
        ctx.fillStyle = '#ef4444';
        ctx.beginPath();
        ctx.arc((food.x + 0.5) * cell, (food.y + 0.5) * cell, cell * 0.38, 0, Math.PI * 2);
        ctx.fill();
      }
      snake.forEach((s, i) => {
        ctx.fillStyle = i === 0 ? '#fde047' : '#facc15';
        roundRect(s.x * cell + 1, s.y * cell + 1, cell - 2, cell - 2, cell * 0.3);
      });
      ctx.strokeStyle = 'rgba(0, 0, 0, .25)';
      ctx.strokeRect(0, 0, size, size);
    }

    function resize() {
      const size = canvas.clientWidth;
      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.round(size * dpr);
      canvas.height = Math.round(size * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      cell = size / GRID;
      draw();
    }

    // ----- Input -----
    const KEYS = {
      ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
      w: 'up', s: 'down', a: 'left', d: 'right', W: 'up', S: 'down', A: 'left', D: 'right'
    };
    document.addEventListener('keydown', (e) => {
      if (KEYS[e.key]) {
        e.preventDefault();
        if (state === 'running') turn(KEYS[e.key]);
      } else if (e.key === ' ') {
        if (e.target instanceof HTMLButtonElement && !overlay.hidden) return; // tombol menangani spasi sendiri
        e.preventDefault();
        if (state === 'running') pause();
        else start();
      }
    });

    let touchStart = null;
    canvas.addEventListener('touchstart', (e) => { touchStart = e.touches[0]; }, { passive: true });
    canvas.addEventListener('touchend', (e) => {
      if (!touchStart) return;
      const t = e.changedTouches[0];
      const dx = t.clientX - touchStart.clientX;
      const dy = t.clientY - touchStart.clientY;
      touchStart = null;
      if (Math.max(Math.abs(dx), Math.abs(dy)) < 24) return;
      turn(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up'));
    });
    document.querySelector('.pad').addEventListener('click', (e) => {
      const button = e.target.closest('[data-dir]');
      if (button && state === 'running') turn(button.dataset.dir);
    });
    playBtn.addEventListener('click', start);
    window.addEventListener('resize', resize);
    document.addEventListener('visibilitychange', () => { if (document.hidden) pause(); });

    reset();
    resize();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Snake dengan canvas** → papan `#board` digambar oleh `draw()` dalam loop `requestAnimationFrame` berinterval langkah tetap.
- **Keyboard** → tombol panah atau WASD (`KEYS`), dan **Spasi** untuk jeda atau lanjut.
- **Swipe di HP** → geser di atas papan, plus tombol arah yang otomatis muncul di perangkat layar sentuh (`pointer: coarse`).
- **Skor tertinggi tersimpan** → disimpan di `localStorage` dengan kunci `BEST_KEY` dan ditampilkan di `#best`.

**Detail teknis**
- Belokan disimpan dalam antrean maksimal 2 langkah, dan belokan 180° diabaikan. Dengan begitu, menekan dua tombol dengan cepat tidak membuat ular menabrak dirinya sendiri.
- Makanan hanya muncul di sel kosong (`spawnFood()`), kecepatan bertambah setiap kali ular makan, dan game dijeda otomatis saat tab disembunyikan.
- Canvas mengikuti `devicePixelRatio`, jadi tetap tajam di layar beresolusi tinggi.

Berikut tic-tac-toe melawan komputer dalam satu file HTML. Pada mode **Mustahil**, komputer memakai algoritma minimax, jadi hasil terbaik yang bisa kamu dapat adalah seri.

```html
<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Tic-Tac-Toe vs Komputer</title>
  <style>
    :root { --bg: #111827; --surface: #1f2937; --cell: #374151; --text: #f9fafb; --muted: #9ca3af; --x: #38bdf8; --o: #f472b6; --win: #22c55e; }
    *, *::before, *::after { box-sizing: border-box; }
    body {
      margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 1rem;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      background: var(--bg); color: var(--text);
    }
    .app { width: min(100%, 400px); text-align: center; }
    h1 { margin: 0 0 .25rem; }
    .subtitle { margin: 0 0 1.25rem; color: var(--muted); }
    .scores { display: grid; grid-template-columns: repeat(3, 1fr); gap: .5rem; margin-bottom: 1rem; }
    .scores div { background: var(--surface); border-radius: 12px; padding: .6rem; }
    .scores span { display: block; font-size: 1.5rem; font-weight: 800; }
    .scores .x span { color: var(--x); }
    .scores .o span { color: var(--o); }
    .status { min-height: 1.6em; font-weight: 700; margin: 0 0 1rem; }
    .board { display: grid; grid-template-columns: repeat(3, 1fr); gap: .6rem; }
    .cell {
      aspect-ratio: 1; border: 0; border-radius: 14px; cursor: pointer;
      background: var(--cell); font: inherit; font-size: clamp(2.5rem, 14vw, 3.5rem); font-weight: 800;
      transition: background-color .15s, transform .1s;
    }
    .cell:hover:not(:disabled) { background: #4b5563; }
    .cell:disabled { cursor: default; }
    .cell.x { color: var(--x); }
    .cell.o { color: var(--o); }
    .cell.win { background: var(--win); color: #052e16; }
    .cell:focus-visible, .btn:focus-visible, select:focus-visible { outline: 3px solid #fde68a; outline-offset: 2px; }
    .controls { display: flex; gap: .75rem; justify-content: center; align-items: center; flex-wrap: wrap; margin-top: 1.25rem; }
    select, .btn { padding: .65rem 1rem; border-radius: 10px; border: 0; font: inherit; }
    select { background: var(--surface); color: var(--text); }
    .btn { background: var(--x); color: #082f49; font-weight: 700; cursor: pointer; }
    @media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
  </style>
</head>
<body>
  <main class="app">
    <h1>Tic-Tac-Toe</h1>
    <p class="subtitle">Kamu <strong style="color: var(--x)">X</strong>, komputer <strong style="color: var(--o)">O</strong>.</p>
    <div class="scores" aria-live="polite">
      <div class="x">Kamu<span id="score-x">0</span></div>
      <div>Seri<span id="score-draw">0</span></div>
      <div class="o">Komputer<span id="score-o">0</span></div>
    </div>
    <p class="status" id="status" role="status"></p>
    <div class="board" id="board" role="group" aria-label="Papan permainan"></div>
    <div class="controls">
      <select id="level" aria-label="Tingkat kesulitan">
        <option value="hard">Mustahil (minimax)</option>
        <option value="easy">Santai (acak)</option>
      </select>
      <button class="btn" id="restart" type="button">Ronde baru</button>
    </div>
  </main>

  <script>
    const LINES = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
    const HUMAN = 'X';
    const AI = 'O';
    const boardEl = document.getElementById('board');
    const statusEl = document.getElementById('status');
    const levelEl = document.getElementById('level');
    const scores = { X: 0, O: 0, draw: 0 };

    let board = Array(9).fill(null);
    let over = false;
    let humanStarts = true;

    const cells = Array.from({ length: 9 }, (_, i) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'cell';
      button.addEventListener('click', () => humanMove(i));
      boardEl.append(button);
      return button;
    });

    function winnerOf(b) {
      for (const line of LINES) {
        const [a, c, d] = line;
        if (b[a] && b[a] === b[c] && b[a] === b[d]) return { player: b[a], line };
      }
      return b.every(Boolean) ? { player: 'draw', line: [] } : null;
    }

    // Minimax: komputer memaksimalkan skor, manusia meminimalkan.
    // Kedalaman ikut dihitung supaya komputer memilih kemenangan tercepat dan kekalahan terlama.
    function minimax(b, isAiTurn, depth) {
      const result = winnerOf(b);
      if (result) {
        if (result.player === AI) return 10 - depth;
        if (result.player === HUMAN) return depth - 10;
        return 0;
      }
      let best = isAiTurn ? -Infinity : Infinity;
      for (let i = 0; i < 9; i++) {
        if (b[i]) continue;
        b[i] = isAiTurn ? AI : HUMAN;
        const score = minimax(b, !isAiTurn, depth + 1);
        b[i] = null;
        best = isAiTurn ? Math.max(best, score) : Math.min(best, score);
      }
      return best;
    }

    function bestMove() {
      const empty = board.map((v, i) => (v ? null : i)).filter((i) => i !== null);
      if (levelEl.value === 'easy') return empty[Math.floor(Math.random() * empty.length)];
      let bestScore = -Infinity;
      let moves = [];
      for (const i of empty) {
        board[i] = AI;
        const score = minimax(board, false, 1);
        board[i] = null;
        if (score > bestScore) { bestScore = score; moves = [i]; }
        else if (score === bestScore) moves.push(i);
      }
      return moves[Math.floor(Math.random() * moves.length)]; // variasi di antara langkah sama bagus
    }

    function render() {
      board.forEach((v, i) => {
        const cell = cells[i];
        cell.textContent = v || '';
        cell.className = 'cell' + (v ? ' ' + v.toLowerCase() : '');
        cell.disabled = Boolean(v) || over;
        const row = Math.floor(i / 3) + 1;
        const col = (i % 3) + 1;
        cell.setAttribute('aria-label', `Baris ${row} kolom ${col}: ${v || 'kosong'}`);
      });
    }

    function finish(result) {
      over = true;
      result.line.forEach((i) => cells[i].classList.add('win'));
      if (result.player === 'draw') {
        scores.draw++;
        statusEl.textContent = 'Seri! Coba lagi.';
      } else {
        scores[result.player]++;
        statusEl.textContent = result.player === HUMAN ? 'Kamu menang!' : 'Komputer menang.';
      }
      document.getElementById('score-x').textContent = scores.X;
      document.getElementById('score-o').textContent = scores.O;
      document.getElementById('score-draw').textContent = scores.draw;
      cells.forEach((c) => { c.disabled = true; });
    }

    function play(index, player) {
      board[index] = player;
      render();
      const result = winnerOf(board);
      if (result) {
        finish(result);
        return true;
      }
      return false;
    }

    function aiTurn() {
      statusEl.textContent = 'Komputer berpikir…';
      cells.forEach((c) => { c.disabled = true; });
      setTimeout(() => {
        if (over) return;
        if (!play(bestMove(), AI)) statusEl.textContent = 'Giliranmu.';
      }, 350);
    }

    function humanMove(i) {
      if (over || board[i]) return;
      if (!play(i, HUMAN)) aiTurn();
    }

    function newRound() {
      board = Array(9).fill(null);
      over = false;
      render();
      if (humanStarts) statusEl.textContent = 'Giliranmu. Kamu jalan duluan.';
      else aiTurn();
      humanStarts = !humanStarts; // bergantian siapa yang mulai
    }

    document.getElementById('restart').addEventListener('click', newRound);
    newRound();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Lawan komputer** → kamu bermain sebagai X dan komputer sebagai O. Giliran pertama bergantian setiap ronde, dan ada papan skor.
- **Tidak bisa dikalahkan** → mode **Mustahil** memakai `minimax()`, yang menelusuri semua kemungkinan langkah sampai permainan selesai. Hasil terbaik yang bisa kamu dapat adalah seri.

**Cara kerja AI**
- Kemenangan komputer bernilai positif, kekalahan negatif, dan seri nol. Kedalaman ikut dihitung (`10 − depth`), sehingga komputer memilih kemenangan tercepat dan menunda kekalahan selama mungkin.
- Jika beberapa langkah sama bagusnya, `bestMove()` memilih secara acak agar permainan tidak monoton.
- Papan 3×3 cukup kecil, sehingga pencarian penuh tetap instan tanpa perlu alpha-beta pruning.

**Fitur lain**
- Mode **Santai** (langkah acak) untuk pemain yang ingin menang, garis kemenangan yang disorot, dan `aria-label` di setiap sel yang menyebut baris, kolom, dan isinya.

Berikut aplikasi pomodoro timer dalam satu file HTML, dengan progress lingkaran dari SVG dan bunyi notifikasi dari Web Audio API, jadi tidak butuh file audio.

```html
<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Pomodoro Timer</title>
  <style>
    :root { --bg: #7f1d1d; --ring: #fecaca; --track: rgba(255, 255, 255, .15); --text: #fff; --muted: rgba(255, 255, 255, .75); }
    body.short { --bg: #134e4a; --ring: #99f6e4; }
    body.long { --bg: #1e3a8a; --ring: #bfdbfe; }
    *, *::before, *::after { box-sizing: border-box; }
    body {
      margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 1rem;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      background: var(--bg); color: var(--text); transition: background-color .4s;
    }
    .app { width: min(100%, 420px); text-align: center; }
    .modes { display: inline-flex; flex-wrap: wrap; justify-content: center; max-width: 100%; gap: .25rem; padding: .25rem; border-radius: 999px; background: rgba(0, 0, 0, .2); margin-bottom: 2rem; }
    .modes button {
      padding: .5rem .85rem; border: 0; border-radius: 999px; cursor: pointer; white-space: nowrap;
      background: transparent; color: var(--muted); font: inherit; font-size: .92rem; font-weight: 600;
    }
    .modes button[aria-pressed="true"] { background: rgba(255, 255, 255, .2); color: var(--text); }
    .ring { position: relative; width: min(100%, 300px); margin: 0 auto; }
    .ring svg { width: 100%; height: auto; transform: rotate(-90deg); display: block; }
    .ring circle { fill: none; stroke-width: 10; }
    .ring .track { stroke: var(--track); }
    .ring .progress { stroke: var(--ring); stroke-linecap: round; transition: stroke-dashoffset .25s linear; }
    .time {
      position: absolute; inset: 0; display: grid; place-content: center;
      font-size: clamp(3rem, 16vw, 4.5rem); font-weight: 700; font-variant-numeric: tabular-nums; letter-spacing: -.02em;
    }
    .label { display: block; font-size: 1rem; font-weight: 500; color: var(--muted); letter-spacing: 0; }
    .controls { display: flex; justify-content: center; gap: 1rem; margin: 2rem 0 1rem; }
    .btn {
      min-width: 140px; padding: .9rem 1.5rem; border: 0; border-radius: 14px; cursor: pointer;
      background: #fff; color: var(--bg); font: inherit; font-size: 1.1rem; font-weight: 800; text-transform: uppercase; letter-spacing: .05em;
    }
    .btn-icon { min-width: 0; width: 56px; padding: 0; display: grid; place-items: center; background: rgba(255, 255, 255, .2); color: #fff; }
    :focus-visible { outline: 3px solid #fff; outline-offset: 3px; }
    .sessions { color: var(--muted); }
    .dots { display: flex; justify-content: center; gap: .5rem; margin-top: .5rem; }
    .dots span { width: 12px; height: 12px; border-radius: 50%; background: var(--track); }
    .dots span.done { background: var(--ring); }
    details { margin-top: 2rem; text-align: left; background: rgba(0, 0, 0, .2); border-radius: 14px; padding: 1rem 1.25rem; }
    summary { cursor: pointer; font-weight: 700; }
    .settings { display: grid; grid-template-columns: repeat(3, 1fr); gap: .75rem; margin-top: 1rem; }
    .settings label { font-size: .85rem; color: var(--muted); }
    .settings input { width: 100%; margin-top: .3rem; padding: .5rem; border: 0; border-radius: 8px; font: inherit; }
    @media (max-width: 360px) { .modes button { padding: .45rem .6rem; font-size: .85rem; } }
    @media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
  </style>
</head>
<body>
  <main class="app">
    <div class="modes" role="group" aria-label="Mode timer">
      <button type="button" data-mode="focus" aria-pressed="true">Fokus</button>
      <button type="button" data-mode="short" aria-pressed="false">Istirahat</button>
      <button type="button" data-mode="long" aria-pressed="false">Istirahat panjang</button>
    </div>

    <div class="ring">
      <svg viewBox="0 0 220 220" aria-hidden="true">
        <circle class="track" cx="110" cy="110" r="100"/>
        <circle class="progress" id="progress" cx="110" cy="110" r="100"/>
      </svg>
      <div class="time" role="timer" aria-live="off">
        <span id="time">25:00</span>
        <span class="label" id="mode-label">Waktunya fokus</span>
      </div>
    </div>

    <div class="controls">
      <button class="btn" id="start-btn" type="button">Mulai</button>
      <button class="btn btn-icon" id="reset-btn" type="button" aria-label="Ulangi sesi">
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5"/></svg>
      </button>
      <button class="btn btn-icon" id="skip-btn" type="button" aria-label="Lewati ke sesi berikutnya">
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 4l10 8-10 8z"/><path d="M19 5v14"/></svg>
      </button>
    </div>

    <p class="sessions" id="sessions" aria-live="polite"></p>
    <div class="dots" id="dots" aria-hidden="true"></div>

    <details>
      <summary>Pengaturan durasi (menit)</summary>
      <div class="settings">
        <label>Fokus<input type="number" id="set-focus" min="1" max="120" value="25"></label>
        <label>Istirahat<input type="number" id="set-short" min="1" max="60" value="5"></label>
        <label>Panjang<input type="number" id="set-long" min="1" max="60" value="15"></label>
      </div>
    </details>
  </main>

  <script>
    const LONG_BREAK_EVERY = 4;
    const LABELS = { focus: 'Waktunya fokus', short: 'Istirahat sebentar', long: 'Istirahat panjang' };
    const $ = (id) => document.getElementById(id);
    const progressEl = $('progress');
    const CIRCUMFERENCE = 2 * Math.PI * 100;
    progressEl.style.strokeDasharray = CIRCUMFERENCE;

    const durations = { focus: 25, short: 5, long: 15 };
    let mode = 'focus';
    let completedFocus = 0;
    let remainingMs = durations.focus * 60 * 1000;
    let endTime = null; // diisi saat timer berjalan
    let intervalId = null;

    const totalMs = () => durations[mode] * 60 * 1000;
    const isRunning = () => endTime !== null;

    function format(ms) {
      const totalSeconds = Math.ceil(ms / 1000);
      const m = String(Math.floor(totalSeconds / 60)).padStart(2, '0');
      const s = String(totalSeconds % 60).padStart(2, '0');
      return `${m}:${s}`;
    }

    function render() {
      const text = format(remainingMs);
      $('time').textContent = text;
      $('mode-label').textContent = LABELS[mode];
      document.title = `${text} · ${LABELS[mode]}`;
      progressEl.style.strokeDashoffset = CIRCUMFERENCE * (1 - remainingMs / totalMs());
      $('start-btn').textContent = isRunning() ? 'Jeda' : remainingMs < totalMs() ? 'Lanjut' : 'Mulai';
      document.body.className = mode === 'focus' ? '' : mode;
      document.querySelectorAll('[data-mode]').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.mode === mode)));
      const inCycle = completedFocus % LONG_BREAK_EVERY;
      $('sessions').textContent = `Sesi fokus selesai hari ini: ${completedFocus}`;
      $('dots').replaceChildren(...Array.from({ length: LONG_BREAK_EVERY }, (_, i) => {
        const dot = document.createElement('span');
        if (i < inCycle || (inCycle === 0 && completedFocus > 0 && mode === 'long')) dot.className = 'done';
        return dot;
      }));
    }

    // Hitung dari selisih waktu nyata, bukan menghitung tick, supaya tetap akurat
    // walaupun browser memperlambat setInterval di tab yang tidak aktif.
    function tick() {
      remainingMs = Math.max(0, endTime - Date.now());
      if (remainingMs === 0) return complete();
      render();
    }

    function start() {
      endTime = Date.now() + remainingMs;
      intervalId = setInterval(tick, 250);
      render();
    }

    function pause() {
      clearInterval(intervalId);
      remainingMs = Math.max(0, endTime - Date.now());
      endTime = null;
      render();
    }

    function setMode(next) {
      clearInterval(intervalId);
      endTime = null;
      mode = next;
      remainingMs = totalMs();
      render();
    }

    function nextMode() {
      if (mode !== 'focus') return 'focus';
      return completedFocus % LONG_BREAK_EVERY === 0 ? 'long' : 'short';
    }

    function complete() {
      clearInterval(intervalId);
      endTime = null;
      if (mode === 'focus') completedFocus++;
      beep();
      setMode(nextMode());
      start(); // sesi berikutnya langsung berjalan
    }

    let audioCtx = null;
    function beep() {
      try {
        audioCtx = audioCtx || new (window.AudioContext || window.webkitAudioContext)();
        [0, 0.25, 0.5].forEach((offset) => {
          const osc = audioCtx.createOscillator();
          const gain = audioCtx.createGain();
          osc.frequency.value = 880;
          gain.gain.setValueAtTime(0.0001, audioCtx.currentTime + offset);
          gain.gain.exponentialRampToValueAtTime(0.3, audioCtx.currentTime + offset + 0.02);
          gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + offset + 0.2);
          osc.connect(gain).connect(audioCtx.destination);
          osc.start(audioCtx.currentTime + offset);
          osc.stop(audioCtx.currentTime + offset + 0.22);
        });
      } catch (e) {
        // Web Audio tidak tersedia: lewati suara.
      }
    }

    $('start-btn').addEventListener('click', () => {
      // AudioContext perlu dibuat dari interaksi pengguna agar boleh berbunyi nanti.
      if (!audioCtx && (window.AudioContext || window.webkitAudioContext)) {
        audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      }
      if (isRunning()) pause();
      else start();
    });
    $('reset-btn').addEventListener('click', () => setMode(mode));
    $('skip-btn').addEventListener('click', () => {
      if (mode === 'focus') completedFocus++;
      setMode(nextMode());
    });
    document.querySelectorAll('[data-mode]').forEach((b) => b.addEventListener('click', () => setMode(b.dataset.mode)));

    [['focus', 'set-focus'], ['short', 'set-short'], ['long', 'set-long']].forEach(([key, id]) => {
      $(id).addEventListener('change', (e) => {
        const value = Math.min(Number(e.target.max), Math.max(1, Math.round(Number(e.target.value) || durations[key])));
        e.target.value = value;
        durations[key] = value;
        if (key === mode && !isRunning()) setMode(mode);
      });
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === ' ' && e.target === document.body) {
        e.preventDefault();
        $('start-btn').click();
      }
    });

    render();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Fokus 25 menit, istirahat 5 menit, istirahat panjang 15 menit setiap 4 sesi** → `nextMode()` mengatur siklus dengan `LONG_BREAK_EVERY = 4`. Durasi setiap mode bisa diubah di pengaturan.
- **Progress berbentuk lingkaran** → lingkaran SVG `#progress` yang `stroke-dashoffset`-nya dihitung dari `CIRCUMFERENCE`.
- **Bunyi saat waktu habis** → `beep()` memakai Web Audio API, jadi tidak butuh file audio.

**Detail**
- Sisa waktu dihitung dari selisih `Date.now()`, bukan jumlah tick `setInterval`, sehingga tetap akurat walaupun browser memperlambat timer di tab yang tidak aktif.
- Tombol mulai/jeda, ulang, dan lewati, serta **Spasi** untuk mulai/jeda. Judul tab menampilkan sisa waktu, dan warna latar berubah sesuai mode.
- Browser hanya mengizinkan suara setelah ada interaksi pengguna, jadi `AudioContext` dibuat saat tombol **Mulai** pertama kali ditekan.

