<body>
  <header class="hero">
    <div class="container">
      <small>Harga</small>
      <h1>Paket sederhana untuk setiap usaha</h1>
      <p>Coba gratis 14 hari tanpa kartu kredit. Ganti atau batalkan paket kapan saja.</p>
      <div class="billing">
        <span id="label-monthly">Bulanan</span>
        <button class="switch" id="billing-switch" type="button" role="switch" aria-checked="false" aria-labelledby="label-yearly"></button>
        <span id="label-yearly">Tahunan</span>
        <span class="save-badge">Hemat 20%</span>
      </div>
    </div>
  </header>

  <main>
    <section class="container plans" id="plans" aria-label="Paket harga"></section>

    <section class="container compare">
      <h2 class="title">Bandingkan fitur</h2>
      <div class="table-wrap">
        <table>
          <thead>
            <tr><th scope="col">Fitur</th><th scope="col">Starter</th><th scope="col">Pro</th><th scope="col">Bisnis</th></tr>
          </thead>
          <tbody id="compare-body"></tbody>
        </table>
      </div>
    </section>

    <section class="container faq">
      <h2 class="title">Pertanyaan yang sering diajukan</h2>
      <div class="faq-list">
        <details>
          <summary>Apakah ada biaya tersembunyi?</summary>
          <p>Tidak ada. Harga yang tertera sudah termasuk pembaruan aplikasi dan dukungan pelanggan. Biaya transaksi QRIS mengikuti ketentuan penyedia pembayaran.</p>
        </details>
        <details>
          <summary>Bisakah saya pindah paket di tengah periode?</summary>
          <p>Bisa. Saat naik paket, kamu hanya membayar selisih untuk sisa periode. Saat turun paket, perubahan berlaku di periode berikutnya.</p>
        </details>
        <details>
          <summary>Apa yang terjadi setelah masa coba gratis selesai?</summary>
          <p>Akunmu otomatis pindah ke mode baca saja. Data tetap aman dan bisa diaktifkan kembali kapan saja dengan memilih paket.</p>
        </details>
        <details>
          <summary>Apakah KasirKu bisa dipakai tanpa internet?</summary>
          <p>Paket Pro dan Bisnis mendukung mode offline. Transaksi disimpan di perangkat dan disinkronkan saat koneksi kembali.</p>
        </details>
      </div>
    </section>
  </main>

  <script>
    const YEARLY_DISCOUNT = 0.2;
    const PLANS = [
      { name: 'Starter', desc: 'Untuk warung dan usaha yang baru mulai.', monthly: 49000, features: ['1 outlet', '1 akun kasir', 'Laporan penjualan harian', 'Pembayaran tunai & QRIS'] },
      { name: 'Pro', desc: 'Untuk kafe dan toko yang sedang berkembang.', monthly: 99000, featured: true, features: ['Hingga 3 outlet', '5 akun kasir', 'Manajemen stok otomatis', 'Mode offline', 'Program loyalitas pelanggan'] },
      { name: 'Bisnis', desc: 'Untuk jaringan usaha dengan banyak cabang.', monthly: 199000, features: ['Outlet tanpa batas', 'Akun kasir tanpa batas', 'Laporan konsolidasi cabang', 'Akses API', 'Dukungan prioritas 24/7'] }
    ];
    const COMPARE = [
      ['Jumlah outlet', '1', '3', 'Tanpa batas'],
      ['Akun kasir', '1', '5', 'Tanpa batas'],
      ['Pembayaran QRIS', true, true, true],
      ['Manajemen stok', false, true, true],
      ['Mode offline', false, true, true],
      ['Laporan multi-cabang', false, false, true],
      ['Akses API', false, false, true]
    ];

    const rupiah = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0, maximumFractionDigits: 0 });
    const plansEl = document.getElementById('plans');
    const switchEl = document.getElementById('billing-switch');
    let yearly = false;

    function priceFor(plan) {
      const perMonth = yearly ? Math.round(plan.monthly * (1 - YEARLY_DISCOUNT) / 1000) * 1000 : plan.monthly;
      return { perMonth, perYear: perMonth * 12 };
    }

    function renderPlans() {
      plansEl.replaceChildren(...PLANS.map((plan) => {
        const { perMonth, perYear } = priceFor(plan);
        const card = document.createElement('article');
        card.className = 'plan' + (plan.featured ? ' featured' : '');
        card.innerHTML = `
          ${plan.featured ? '<span class="popular">Paling populer</span>' : ''}
          <h2></h2>
          <p class="desc"></p>
          <div class="price"><span class="amount"></span> <small>/bulan</small></div>
          <p class="billed"></p>
          <a class="cta" href="#">Coba gratis 14 hari</a>
          <ul class="features"></ul>`;
        card.querySelector('h2').textContent = plan.name;
        card.querySelector('.desc').textContent = plan.desc;
        card.querySelector('.amount').textContent = rupiah.format(perMonth);
        card.querySelector('.billed').textContent = yearly
          ? `Ditagih ${rupiah.format(perYear)} per tahun`
          : 'Ditagih setiap bulan';
        card.querySelector('.cta').setAttribute('aria-label', `Coba gratis paket ${plan.name}`);
        card.querySelector('.features').append(...plan.features.map((f) => Object.assign(document.createElement('li'), { textContent: f })));
        return card;
      }));
    }

    function renderCompare() {
      document.getElementById('compare-body').replaceChildren(...COMPARE.map(([feature, ...values]) => {
        const tr = document.createElement('tr');
        const th = Object.assign(document.createElement('th'), { scope: 'row', textContent: feature });
        th.style.fontWeight = '500';
        tr.append(th);
        values.forEach((v) => {
          const td = document.createElement('td');
          if (typeof v === 'boolean') {
            const mark = Object.assign(document.createElement('span'), { className: v ? 'yes' : 'no', textContent: v ? '✓' : '—' });
            mark.setAttribute('aria-label', v ? 'Termasuk' : 'Tidak termasuk');
            td.append(mark);
          } else {
            td.textContent = v;
          }
          tr.append(td);
        });
        return tr;
      }));
    }

    switchEl.addEventListener('click', () => {
      yearly = !yearly;
      switchEl.setAttribute('aria-checked', String(yearly));
      renderPlans();
    });

    renderPlans();
    renderCompare();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **3 paket** → kartu paket dirender dari `PLANS` oleh `renderPlans()`, dengan paket unggulan berlabel "Paling populer".
- **Toggle bulanan/tahunan dengan diskon 20%** → `#billing-switch` memakai `role="switch"`. `priceFor()` menghitung harga tahunan dari `YEARLY_DISCOUNT`, membulatkannya ke ribuan terdekat, dan menampilkan total tagihan per tahun.
- **Tabel perbandingan fitur** → `renderCompare()` membuat tabel dari `COMPARE`. Di layar kecil, tabelnya bisa digeser horizontal.
- **FAQ** → elemen native `<details>` dan `<summary>`, sehingga bisa dibuka dengan keyboard tanpa JavaScript tambahan.

**Cara menyesuaikan**
- Ubah `YEARLY_DISCOUNT`, `PLANS`, dan `COMPARE`, lalu arahkan tombol "Coba gratis" ke halaman pendaftaranmu.

