  <script>
    const $ = (id) => document.getElementById(id);
    const rupiah = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0, maximumFractionDigits: 0 });
    const inputs = ['price', 'dp', 'tenor', 'rate'].map($);

    // Rumus anuitas: M = P × r / (1 − (1 + r)^−n)
    function monthlyPayment(principal, monthlyRate, months) {
      if (monthlyRate === 0) return principal / months;
      return principal * monthlyRate / (1 - Math.pow(1 + monthlyRate, -months));
    }

    function buildSchedule(principal, monthlyRate, months, payment) {
      const years = [];
      let balance = principal;
      for (let m = 1; m <= months; m++) {
        const interest = balance * monthlyRate;
        // Bulan terakhir melunasi sisa supaya pembulatan floating point tidak menyisakan saldo.
        const principalPart = m === months ? balance : payment - interest;
        balance -= principalPart;
        const y = Math.ceil(m / 12) - 1;
        years[y] = years[y] || { principal: 0, interest: 0, balance: 0 };
        years[y].principal += principalPart;
        years[y].interest += interest;
        years[y].balance = Math.max(0, balance);
      }
      return years;
    }

    // Mengembalikan [id input yang salah, pesan] atau null jika semua valid.
    function validate(price, dpPct, tenor, rate) {
      if (!(price >= 1e6)) return ['price', 'Harga rumah minimal Rp1.000.000.'];
      if (!(dpPct >= 0 && dpPct < 100)) return ['dp', 'Uang muka harus antara 0% dan di bawah 100%.'];
      if (!(Number.isInteger(tenor) && tenor >= 1 && tenor <= 30)) return ['tenor', 'Jangka waktu harus bilangan bulat 1–30 tahun.'];
      if (!(rate >= 0 && rate <= 30)) return ['rate', 'Suku bunga harus antara 0% dan 30% per tahun.'];
      return null;
    }

    function calculate() {
      const price = parseFloat($('price').value);
      const dpPct = parseFloat($('dp').value);
      const tenor = Number($('tenor').value);
      const rate = parseFloat($('rate').value);
      const problem = validate(price, dpPct, tenor, rate);
      inputs.forEach((i) => i.setAttribute('aria-invalid', String(Boolean(problem) && i.id === problem[0])));
      $('error').textContent = problem ? problem[1] : '';
      if (problem) return;

      const dp = price * dpPct / 100;
      const principal = price - dp;
      const months = tenor * 12;
      const monthlyRate = rate / 100 / 12;
      const payment = monthlyPayment(principal, monthlyRate, months);
      const totalPaid = payment * months;
      const totalInterest = totalPaid - principal;

      $('price-text').textContent = rupiah.format(price);
      $('dp-text').textContent = `Uang muka ${rupiah.format(dp)}`;
      $('monthly').textContent = rupiah.format(payment);
      $('loan').textContent = rupiah.format(principal);
      $('interest').textContent = rupiah.format(totalInterest);
      $('total').textContent = rupiah.format(totalPaid);
      $('count').textContent = `${months} bulan`;

      const principalShare = totalPaid > 0 ? (principal / totalPaid) * 100 : 100;
      $('split-principal').style.width = `${principalShare}%`;
      $('split-interest').style.width = `${100 - principalShare}%`;
      const pct = (v) => v.toLocaleString('id-ID', { maximumFractionDigits: 1 });
      $('legend-principal').textContent = `Pokok ${pct(principalShare)}%`;
      $('legend-interest').textContent = `Bunga ${pct(100 - principalShare)}%`;

      $('schedule').replaceChildren(...buildSchedule(principal, monthlyRate, months, payment).map((y, i) => {
        const tr = document.createElement('tr');
        [`Tahun ${i + 1}`, rupiah.format(y.principal), rupiah.format(y.interest), rupiah.format(y.balance)].forEach((text) => {
          tr.append(Object.assign(document.createElement('td'), { textContent: text }));
        });
        return tr;
      }));
    }

    $('form').addEventListener('input', calculate);
    $('form').addEventListener('submit', (e) => e.preventDefault());
    calculate();
  </script>
</body>
</html>
```

**Rumus**
```
M = P × r / (1 − (1 + r)^−n)
```
`P` adalah pokok pinjaman (harga rumah − uang muka), `r` adalah suku bunga per bulan (bunga tahunan ÷ 12), dan `n` adalah jumlah bulan. Jika bunga 0%, cicilan menjadi `P ÷ n`.

**Cek kebutuhan**
- **Input harga rumah, DP (persen), tenor (tahun), dan suku bunga per tahun** → empat kolom di `#form`, divalidasi `validate()` yang menandai kolom salah dengan `aria-invalid`.
- **Cicilan per bulan** → `monthlyPayment()` dengan rumus di atas, diperbarui setiap kali input berubah.
- **Total bunga** → ditampilkan bersama pokok pinjaman, total pembayaran, dan perbandingan porsi pokok serta bunga.
- **Tabel angsuran per tahun** → `buildSchedule()` merekap pokok, bunga, dan sisa pinjaman per tahun. Di bulan terakhir, sisa saldo dilunasi tepat supaya tidak tersisa saldo akibat pembulatan.

Dengan nilai bawaan (harga Rp750 juta, DP 20%, tenor 15 tahun, bunga 7,5%), pokok pinjaman Rp600 juta dan cicilannya sekitar Rp5,56 juta per bulan.

**Catatan:** banyak KPR di Indonesia memakai bunga tetap hanya untuk beberapa tahun pertama, lalu beralih ke bunga mengambang. Biaya provisi, asuransi, notaris, dan pajak juga belum termasuk. Disclaimer ini ikut ditampilkan di halaman.

