  </button>

  <script>
    const article = document.getElementById('article');
    const progress = document.getElementById('progress');
    const toTop = document.getElementById('to-top');
    const tocList = document.getElementById('toc-list');
    const WORDS_PER_MINUTE = 200;

    // Estimasi waktu baca
    const words = article.innerText.trim().split(/\s+/).length;
    document.getElementById('reading-time').textContent = `${Math.max(1, Math.round(words / WORDS_PER_MINUTE))} menit baca`;

    // Daftar isi otomatis dari h2 dan h3
    const slugify = (text) => text.toLowerCase().normalize('NFKD').replace(/[^\w\s-]/g, '').trim().replace(/\s+/g, '-');
    const headings = [...article.querySelectorAll('h2, h3')];
    const links = headings.map((h) => {
      if (!h.id) h.id = slugify(h.textContent);
      const li = document.createElement('li');
      const a = document.createElement('a');
      a.href = `#${h.id}`;
      a.textContent = h.textContent;
      if (h.tagName === 'H3') a.className = 'sub';
      li.append(a);
      tocList.append(li);
      return a;
    });

    // Di layar kecil daftar isi dimulai tertutup agar tidak menutupi artikel
    if (matchMedia('(max-width: 900px)').matches) document.querySelector('.toc details').open = false;

    // Bagian aktif = heading terakhir yang sudah melewati 30% bagian atas layar
    function updateActive() {
      const threshold = window.innerHeight * 0.3;
      let current = headings[0];
      for (const h of headings) {
        if (h.getBoundingClientRect().top > threshold) break;
        current = h;
      }
      links.forEach((a) => {
        const active = a.getAttribute('href') === `#${current.id}`;
        a.classList.toggle('active', active);
        if (active) a.setAttribute('aria-current', 'true');
        else a.removeAttribute('aria-current');
      });
    }

    // Progress bar, bagian aktif, dan tombol kembali ke atas
    let ticking = false;
    function onScroll() {
      updateActive();
      const start = article.offsetTop;
      const end = article.offsetTop + article.offsetHeight - window.innerHeight;
      const ratio = end > start ? (window.scrollY - start) / (end - start) : 1;
      progress.style.transform = `scaleX(${Math.min(1, Math.max(0, ratio))})`;
      toTop.classList.toggle('visible', window.scrollY > 600);
      ticking = false;
    }
    window.addEventListener('scroll', () => {
      if (!ticking) {
        ticking = true;
        requestAnimationFrame(onScroll);
      }
    }, { passive: true });
    toTop.addEventListener('click', () => {
      window.scrollTo({ top: 0 });
      document.querySelector('h1').setAttribute('tabindex', '-1');
      document.querySelector('h1').focus({ preventScroll: true });
    });
    onScroll();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Nyaman dibaca** → lebar teks sekitar 70 karakter, font serif untuk isi artikel, dan blok kode yang bisa digeser tanpa membuat halaman melebar.
- **Progress bar baca** → `#progress`, dihitung dari posisi artikel (bukan seluruh halaman) dan diperbarui lewat `requestAnimationFrame` di `onScroll()`.
- **Daftar isi otomatis dari heading** → dibuat dari semua `h2` dan `h3` ke `#toc-list`. Heading yang belum punya `id` dibuatkan slug, dan `updateActive()` menyorot bagian yang sedang dibaca dengan `aria-current`.
- **Estimasi waktu baca** → jumlah kata dibagi `WORDS_PER_MINUTE` (200), lalu ditampilkan di `#reading-time`.
- **Tombol kembali ke atas** → `#to-top` muncul setelah halaman digulir 600px dan memindahkan fokus ke judul.

**Cara memakai**
- Ganti isi `<article>` dengan artikelmu. Daftar isi dan estimasi waktu baca akan menyesuaikan otomatis. Di layar kecil, daftar isi pindah ke atas artikel dalam `<details>`.

