          <div class="field">
            <label for="birthDate">Tanggal lahir</label>
            <input id="birthDate" name="birthDate" type="date" autocomplete="bday">
          </div>
        </div>
      </fieldset>

      <fieldset data-step="1" hidden>
        <legend>Alamat</legend>
        <div class="grid">
          <div class="field full">
            <label for="street">Alamat lengkap</label>
            <textarea id="street" name="street" autocomplete="street-address" placeholder="Nama jalan, nomor rumah, RT/RW"></textarea>
          </div>
          <div class="field">
            <label for="city">Kota/Kabupaten</label>
            <input id="city" name="city" autocomplete="address-level2">
          </div>
          <div class="field">
            <label for="postalCode">Kode pos</label>
            <input id="postalCode" name="postalCode" inputmode="numeric" autocomplete="postal-code" maxlength="5">
          </div>
        </div>
      </fieldset>

      <fieldset data-step="2" hidden>
        <legend>Akun</legend>
        <div class="field">
          <label for="email">Email</label>
          <input id="email" name="email" type="email" autocomplete="email">
        </div>
        <div class="field">
          <label for="password">Kata sandi</label>
          <input id="password" name="password" type="password" autocomplete="new-password" aria-describedby="password-hint">
          <div class="strength" aria-hidden="true"><div id="strength-bar"></div></div>
          <p class="hint" id="password-hint">Minimal 8 karakter, berisi huruf besar, huruf kecil, dan angka.</p>
        </div>
        <div class="field">
          <label for="confirm">Ulangi kata sandi</label>
          <input id="confirm" name="confirm" type="password" autocomplete="new-password">
        </div>
        <div class="field">
          <label class="check"><input type="checkbox" id="terms" name="terms"> Saya menyetujui syarat dan ketentuan serta kebijakan privasi.</label>
        </div>
      </fieldset>

      <fieldset data-step="3" hidden>
        <legend>Periksa kembali data kamu</legend>
        <div class="summary" id="summary"></div>
      </fieldset>

      <div class="actions">
        <button class="btn secondary" type="button" id="back">Kembali</button>
        <button class="btn" type="submit" id="next">Lanjut</button>
      </div>
    </form>

    <div class="success" id="success" hidden tabindex="-1">
      <div class="icon" aria-hidden="true">✓</div>
      <h2>Pendaftaran berhasil!</h2>
      <p id="success-text"></p>
    </div>
  </main>

  <script>
    const form = document.getElementById('form');
    const stepEls = [...form.querySelectorAll('fieldset[data-step]')];
    const indicator = [...document.querySelectorAll('#steps li')];
    const backBtn = document.getElementById('back');
    const nextBtn = document.getElementById('next');
    let step = 0;

    const value = (name) => form.elements[name].value.trim();

    function ageFrom(dateString) {
      const birth = new Date(`${dateString}T00:00:00`);
      const today = new Date();
      let age = today.getFullYear() - birth.getFullYear();
      const beforeBirthday = today.getMonth() < birth.getMonth() ||
        (today.getMonth() === birth.getMonth() && today.getDate() < birth.getDate());
      return beforeBirthday ? age - 1 : age;
    }

    // Setiap aturan mengembalikan pesan error, atau string kosong jika valid.
    const RULES = {
      fullName: () => (value('fullName').length >= 3 ? '' : 'Nama minimal 3 karakter.'),
      phone: () => (/^(\+62|62|0)8\d{7,11}$/.test(value('phone').replace(/[\s-]/g, '')) ? '' : 'Nomor HP tidak valid. Contoh: 081234567890.'),
      birthDate: () => {
        if (!value('birthDate')) return 'Tanggal lahir wajib diisi.';
        const age = ageFrom(value('birthDate'));
        if (age < 17) return 'Usia minimal 17 tahun.';
        if (age > 120) return 'Periksa kembali tahun lahir.';
        return '';
      },
      street: () => (value('street').length >= 10 ? '' : 'Alamat terlalu pendek.'),
      city: () => (value('city') ? '' : 'Kota wajib diisi.'),
      postalCode: () => (/^\d{5}$/.test(value('postalCode')) ? '' : 'Kode pos harus 5 digit angka.'),
      email: () => (/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value('email')) ? '' : 'Format email tidak valid.'),
      password: () => {
        const p = form.elements.password.value;
        return p.length >= 8 && /[a-z]/.test(p) && /[A-Z]/.test(p) && /\d/.test(p) ? '' : 'Kata sandi belum memenuhi syarat.';
      },
      confirm: () => (form.elements.confirm.value && form.elements.confirm.value === form.elements.password.value ? '' : 'Kata sandi tidak sama.'),
      terms: () => (form.elements.terms.checked ? '' : 'Kamu perlu menyetujui syarat dan ketentuan.')
    };

    function showError(input, message) {
      const field = input.closest('.field');
      let error = field.querySelector('.error');
      if (!error) {
        error = document.createElement('p');
        error.className = 'error';
        error.id = `${input.id}-error`;
        field.append(error);
      }
      error.textContent = message;
      input.setAttribute('aria-invalid', String(Boolean(message)));
      const describedBy = new Set((input.getAttribute('aria-describedby') || '').split(' ').filter(Boolean));
      if (message) describedBy.add(error.id);
      else describedBy.delete(error.id);
      input.setAttribute('aria-describedby', [...describedBy].join(' '));
    }

    function validateStep(index) {
      const inputs = [...stepEls[index].querySelectorAll('input, textarea, select')].filter((i) => RULES[i.name]);
      let firstInvalid = null;
      for (const input of inputs) {
        const message = RULES[input.name]();
        showError(input, message);
        if (message && !firstInvalid) firstInvalid = input;
      }
      if (firstInvalid) firstInvalid.focus();
      return !firstInvalid;
    }

    function renderSummary() {
      const dateText = new Intl.DateTimeFormat('id-ID', { dateStyle: 'long' }).format(new Date(`${value('birthDate')}T00:00:00`));
      const sections = [
        { title: 'Data diri', step: 0, rows: [['Nama', value('fullName')], ['Nomor HP', value('phone')], ['Tanggal lahir', dateText]] },
        { title: 'Alamat', step: 1, rows: [['Alamat', value('street')], ['Kota', value('city')], ['Kode pos', value('postalCode')]] },
        { title: 'Akun', step: 2, rows: [['Email', value('email')], ['Kata sandi', '•'.repeat(8)]] }
      ];
      document.getElementById('summary').replaceChildren(...sections.map((s) => {
        const section = document.createElement('section');
        const header = document.createElement('header');
        const h3 = Object.assign(document.createElement('h3'), { textContent: s.title });
        const edit = Object.assign(document.createElement('button'), { type: 'button', className: 'link-btn', textContent: 'Ubah' });
        edit.setAttribute('aria-label', `Ubah ${s.title.toLowerCase()}`);
        edit.addEventListener('click', () => goTo(s.step));
        header.append(h3, edit);
        const dl = document.createElement('dl');
        s.rows.forEach(([k, v]) => dl.append(
          Object.assign(document.createElement('dt'), { textContent: k }),
          Object.assign(document.createElement('dd'), { textContent: v })
        ));
        section.append(header, dl);
        return section;
      }));
    }

    function goTo(index) {
      step = index;
      stepEls.forEach((el, i) => { el.hidden = i !== step; });
      indicator.forEach((li, i) => {
        li.classList.toggle('done', i < step);
        if (i === step) li.setAttribute('aria-current', 'step');
        else li.removeAttribute('aria-current');
      });
      backBtn.hidden = step === 0;
      nextBtn.textContent = step === stepEls.length - 1 ? 'Kirim pendaftaran' : 'Lanjut';
      if (step === stepEls.length - 1) renderSummary();
      stepEls[step].querySelector('legend').scrollIntoView({ block: 'nearest' });
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      if (step < stepEls.length - 1) {
        if (validateStep(step)) goTo(step + 1);
        return;
      }
      // Langkah terakhir: kirim ke server di sini, misalnya dengan fetch('/api/daftar', ...).
      form.hidden = true;
      document.getElementById('steps').hidden = true;
      document.getElementById('success-text').textContent = `Tautan verifikasi telah dikirim ke ${value('email')}.`;
      const success = document.getElementById('success');
      success.hidden = false;
      success.focus();
    });

    backBtn.addEventListener('click', () => goTo(step - 1));

    // Validasi ulang saat pengguna memperbaiki isian yang salah
    form.addEventListener('input', (e) => {
      if (e.target.getAttribute('aria-invalid') === 'true' && RULES[e.target.name]) showError(e.target, RULES[e.target.name]());
      if (e.target.name === 'password') updateStrength(e.target.value);
    });

    function updateStrength(p) {
      const score = [p.length >= 8, p.length >= 12, /[a-z]/.test(p) && /[A-Z]/.test(p), /\d/.test(p), /[^\w\s]/.test(p)].filter(Boolean).length;
      const colors = ['#dc2626', '#dc2626', '#f59e0b', '#f59e0b', '#16a34a', '#16a34a'];
      const bar = document.getElementById('strength-bar');
      bar.style.width = `${(score / 5) * 100}%`;
      bar.style.backgroundColor = colors[score];
    }

    goTo(0);
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Multi-step: data diri, alamat, akun** → satu `<form>` dengan satu `<fieldset>` per langkah, dipindah oleh `goTo()`. Tombol Enter tetap berfungsi.
  1. Data diri: nama, nomor HP format Indonesia (`08…`, `628…`, atau `+628…`), dan tanggal lahir dengan usia minimal 17 tahun (`ageFrom()`).
  2. Alamat: alamat lengkap, kota, dan kode pos 5 digit.
  3. Akun: email, kata sandi dengan indikator kekuatan (`updateStrength()`), konfirmasi kata sandi, dan persetujuan syarat.
- **Indikator langkah** → `#steps`, dengan `aria-current="step"` pada langkah aktif.
- **Validasi di setiap langkah** → `validateStep()` hanya memeriksa langkah aktif dengan `RULES`. `showError()` menghubungkan pesan ke input lewat `aria-describedby`, dan fokus pindah ke kolom pertama yang salah.
- **Ringkasan sebelum dikirim** → `renderSummary()` menampilkan semua data, dengan tombol **Ubah** di setiap bagian untuk kembali ke langkah terkait.

**Penting:** validasi di browser hanya untuk kenyamanan pengguna. Server tetap harus memvalidasi ulang semua data.

