      const diff = EVENT_START - Date.now();
      if (diff <= 0) {
        $('countdown').hidden = true;
        $('countdown-done').hidden = false;
        clearInterval(countdownTimer);
        return;
      }
      const s = Math.floor(diff / 1000);
      $('cd-days').textContent = Math.floor(s / 86400);
      $('cd-hours').textContent = String(Math.floor((s % 86400) / 3600)).padStart(2, '0');
      $('cd-minutes').textContent = String(Math.floor((s % 3600) / 60)).padStart(2, '0');
      $('cd-seconds').textContent = String(s % 60).padStart(2, '0');
    }
    const countdownTimer = setInterval(updateCountdown, 1000);
    updateCountdown();

    // File kalender .ics
    $('save-date').addEventListener('click', () => {
      const stamp = (d) => d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
      const ics = [
        'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Undangan Dimas Ayu//ID', 'BEGIN:VEVENT',
        `UID:dimas-ayu-20270612@undangan`, `DTSTAMP:${stamp(new Date())}`,
        `DTSTART:${stamp(EVENT_START)}`, `DTEND:${stamp(EVENT_END)}`,
        'SUMMARY:Pernikahan Dimas & Ayu', 'LOCATION:Gedung Serbaguna Melati\\, Yogyakarta',
        'END:VEVENT', 'END:VCALENDAR'
      ].join('\r\n');
      const url = URL.createObjectURL(new Blob([ics], { type: 'text/calendar' }));
      const a = Object.assign(document.createElement('a'), { href: url, download: 'pernikahan-dimas-ayu.ics' });
      document.body.append(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    });

    // RSVP dan ucapan. Data disimpan di perangkat tamu (localStorage) sebagai contoh;
    // untuk undangan sungguhan, kirim ke backend agar semua tamu bisa melihat ucapan.
    function loadWishes() {
      try {
        const data = JSON.parse(localStorage.getItem(WISHES_KEY) || '[]');
        return Array.isArray(data) ? data : [];
      } catch (e) {
        return [];
      }
    }
    let wishes = loadWishes();

    function renderWishes() {
      $('wishes').replaceChildren(...wishes.map((w) => {
        const li = document.createElement('li');
        const name = Object.assign(document.createElement('strong'), { textContent: w.name });
        const badge = Object.assign(document.createElement('span'), { className: 'badge', textContent: w.attend === 'Hadir' ? `Hadir · ${w.count} orang` : w.attend });
        li.append(name, badge);
        if (w.message) li.append(Object.assign(document.createElement('p'), { textContent: w.message }));
        return li;
      }));
    }

    $('rsvp').addEventListener('submit', (e) => {
      e.preventDefault();
      const form = e.target;
      const name = form.elements.name.value.trim();
      if (name.length < 2) {
        $('rsvp-error').textContent = 'Mohon isi nama kamu.';
        form.elements.name.setAttribute('aria-invalid', 'true');
        form.elements.name.focus();
        return;
      }
      $('rsvp-error').textContent = '';
      form.elements.name.removeAttribute('aria-invalid');
      wishes.unshift({
        name,
        attend: form.elements.attend.value,
        count: form.elements.attend.value === 'Tidak hadir' ? 0 : Number(form.elements.count.value),
        message: form.elements.message.value.trim()
      });
      try { localStorage.setItem(WISHES_KEY, JSON.stringify(wishes.slice(0, 50))); } catch (err) { /* abaikan */ }
      form.reset();
      renderWishes();
    });

    renderWishes();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Tombol buka undangan dan nama tamu dari link** → sampul `#cover` membaca parameter `?to=`, contoh `undangan.html?to=Ibu%20Sari`. Nama dipasang dengan `textContent`, jadi parameter berisi HTML tidak dieksekusi, dan konten di belakang sampul diberi atribut `inert`.
- **Countdown** → `updateCountdown()` menghitung mundur ke `EVENT_START` (12 Juni 2027 pukul 08.00 WIB, ditulis dengan `+07:00` agar benar di zona waktu mana pun). Setelah acara lewat, hitung mundur diganti ucapan terima kasih.
- **Info akad dan resepsi** → kartu Akad Nikah dan Resepsi beserta tautan lokasi, plus tombol **Simpan ke Kalender** yang membuat file `.ics`.
- **Galeri** → kisi foto dengan placeholder.
- **Form RSVP** → nama, kehadiran, jumlah tamu, dan ucapan. Ucapan tampil di `#wishes` lewat `renderWishes()`.

**Sebelum disebar**
- Ganti placeholder foto dan tautan "Lihat Lokasi" dengan foto dan link Google Maps yang asli.
- Ucapan disimpan di `localStorage` perangkat masing-masing tamu. Agar bisa dilihat semua tamu dan direkap, kirim data form ke backend, misalnya Google Apps Script, Firebase, atau server sendiri.

