  <style>
    :root { --bg: #f6f8fa; --surface: #ffffff; --text: #1f2328; --muted: #656d76; --border: #d0d7de; --brand: #0969da; --code-bg: #f6f8fa; }
    *, *::before, *::after { box-sizing: border-box; }
    html, body { height: 100%; }
    body { margin: 0; display: flex; flex-direction: column; font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; background: var(--bg); color: var(--text); }
    :focus-visible { outline: 2px solid var(--brand); outline-offset: 1px; }
