<body>
  <header>
    <h1>Papan Kanban</h1>
    <p>Seret kartu antarkolom, atau pakai tombol panah. Semua perubahan tersimpan otomatis.</p>
  </header>

  <main class="board" id="board"></main>
  <p class="sr-only" id="announcer" aria-live="polite"></p>

  <script>
    const STORAGE_KEY = 'kanban-board-v1';
    const COLUMNS = [
      { id: 'todo', title: 'To Do', color: '#94a3b8' },
      { id: 'doing', title: 'Dikerjakan', color: '#f59e0b' },
      { id: 'done', title: 'Selesai', color: '#22c55e' }
    ];
    const SAMPLE = [
      { id: 'c1', text: 'Riset kebutuhan pengguna', column: 'done' },
      { id: 'c2', text: 'Desain halaman beranda', column: 'doing' },
      { id: 'c3', text: 'Siapkan database produk', column: 'todo' },
      { id: 'c4', text: 'Tulis pengujian untuk keranjang', column: 'todo' }
    ];

    const board = document.getElementById('board');
    const announcer = document.getElementById('announcer');
    let cards = load();

    function load() {
      try {
        const data = JSON.parse(localStorage.getItem(STORAGE_KEY));
        if (Array.isArray(data)) return data.filter((c) => c && typeof c.text === 'string' && COLUMNS.some((col) => col.id === c.column));
      } catch (e) { /* data rusak: pakai contoh */ }
      return SAMPLE;
    }
    function save() {
      try { localStorage.setItem(STORAGE_KEY, JSON.stringify(cards)); } catch (e) { /* abaikan */ }
    }
    const newId = () => 'c' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    const columnTitle = (id) => COLUMNS.find((c) => c.id === id).title;

    function render() {
      board.replaceChildren(...COLUMNS.map((col, colIndex) => {
        const items = cards.filter((c) => c.column === col.id);
        const section = document.createElement('section');
        section.className = 'column';
        section.dataset.column = col.id;
        section.style.setProperty('--dot', col.color);
        section.setAttribute('aria-labelledby', `title-${col.id}`);
        section.innerHTML = `
          <div class="column-head"><h2 id="title-${col.id}"></h2><span class="count"></span></div>
          <ul class="cards"></ul>
          <form class="add-form">
            <label class="sr-only" for="add-${col.id}"></label>
            <input id="add-${col.id}" maxlength="140" placeholder="Tambah kartu…" autocomplete="off">
            <button type="submit">Tambah</button>
          </form>`;
        section.querySelector('h2').textContent = col.title;
        section.querySelector('.count').textContent = items.length;
        section.querySelector('label').textContent = `Kartu baru di kolom ${col.title}`;
        section.querySelector('.cards').append(...items.map((card) => {
          const li = document.createElement('li');
          li.className = 'card';
          li.draggable = true;
          li.dataset.id = card.id;
          const text = Object.assign(document.createElement('p'), { textContent: card.text });
          const actions = document.createElement('div');
          actions.className = 'card-actions';
          const prev = COLUMNS[colIndex - 1];
          const next = COLUMNS[colIndex + 1];
          actions.append(
            button('◀', 'move', prev ? `Pindahkan "${card.text}" ke ${prev.title}` : '', !prev, { target: prev && prev.id }),
            button('▶', 'move', next ? `Pindahkan "${card.text}" ke ${next.title}` : '', !next, { target: next && next.id }),
            button('✕', 'delete', `Hapus "${card.text}"`, false, {})
          );
          li.append(text, actions);
          return li;
        }));
        return section;
      }));
    }

    function button(label, action, ariaLabel, disabled, data) {
      const b = Object.assign(document.createElement('button'), { type: 'button', textContent: label, className: action, disabled });
      b.dataset.action = action;
      if (data.target) b.dataset.target = data.target;
      if (ariaLabel) b.setAttribute('aria-label', ariaLabel);
      return b;
    }

    function moveCard(id, column, beforeId = null) {
      const card = cards.find((c) => c.id === id);
      if (!card || id === beforeId) return;
      cards = cards.filter((c) => c.id !== id);
      const moved = { ...card, column };
      const index = beforeId ? cards.findIndex((c) => c.id === beforeId) : -1;
      if (index === -1) cards.push(moved);
      else cards.splice(index, 0, moved);
      save();
      render();
      announcer.textContent = `"${card.text}" dipindahkan ke ${columnTitle(column)}.`;
    }

    // Tombol pada kartu: pindah kolom dan hapus
    board.addEventListener('click', (e) => {
      const b = e.target.closest('button[data-action]');
      if (!b) return;
      const id = b.closest('.card').dataset.id;
      if (b.dataset.action === 'move') {
        moveCard(id, b.dataset.target);
        const moved = board.querySelector(`.card[data-id="${id}"] button[data-action="move"]:not(:disabled)`);
        if (moved) moved.focus();
      } else {
        const card = cards.find((c) => c.id === id);
        cards = cards.filter((c) => c.id !== id);
        save();
        render();
        announcer.textContent = `"${card.text}" dihapus.`;
      }
    });

    // Tambah kartu
    board.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = e.target.querySelector('input');
      const text = input.value.trim();
      if (!text) return;
      const column = e.target.closest('.column').dataset.column;
      cards.push({ id: newId(), text, column });
      save();
      render();
      document.getElementById(`add-${column}`).focus();
    });

    // Drag and drop (HTML5). Di perangkat sentuh, gunakan tombol panah.
    board.addEventListener('dragstart', (e) => {
      const card = e.target.closest('.card');
      if (!card) return;
      e.dataTransfer.setData('text/plain', card.dataset.id);
      e.dataTransfer.effectAllowed = 'move';
      card.classList.add('dragging');
    });
    board.addEventListener('dragend', (e) => {
      e.target.closest('.card')?.classList.remove('dragging');
      board.querySelectorAll('.column.over').forEach((c) => c.classList.remove('over'));
    });
    board.addEventListener('dragover', (e) => {
      const column = e.target.closest('.column');
      if (!column) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      column.classList.add('over');
    });
    board.addEventListener('dragleave', (e) => {
      const column = e.target.closest('.column');
      if (column && !column.contains(e.relatedTarget)) column.classList.remove('over');
    });
    board.addEventListener('drop', (e) => {
      const column = e.target.closest('.column');
      if (!column) return;
      e.preventDefault();
      const id = e.dataTransfer.getData('text/plain');
      // Sisipkan sebelum kartu pertama yang titik tengahnya berada di bawah kursor
      const before = [...column.querySelectorAll('.card:not(.dragging)')]
        .find((c) => e.clientY < c.getBoundingClientRect().top + c.offsetHeight / 2);
      moveCard(id, column.dataset.column, before ? before.dataset.id : null);
    });

    render();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **3 kolom (To Do, Dikerjakan, Selesai)** → didefinisikan di `COLUMNS` dan dirender oleh `render()`.
- **Drag antar kolom** → HTML5 Drag and Drop API. Kartu disisipkan di posisi kursor, dan kolom tujuan disorot. Tombol ◀ ▶ (`moveCard()`) menjadi alternatif untuk HP dan keyboard, karena drag-and-drop HTML5 tidak berjalan di sebagian besar browser mobile. Setiap perpindahan diumumkan lewat `#announcer` (`aria-live`).
- **Tambah dan hapus kartu** → form tambah di setiap kolom, tombol hapus di setiap kartu, dan penghitung jumlah kartu.
- **Tersimpan otomatis** → `save()` ke `localStorage` setiap ada perubahan, dan `load()` mengabaikan data yang rusak atau berisi kolom yang tidak dikenal.

**Cara menyesuaikan**
- Tambah kolom baru, misalnya "Review", cukup lewat array `COLUMNS`.

