    const links = document.getElementById('links');
    function setMenu(open) {
      links.classList.toggle('open', open);
      menuBtn.setAttribute('aria-expanded', String(open));
      menuBtn.setAttribute('aria-label', open ? 'Tutup menu' : 'Buka menu');
    }
    menuBtn.addEventListener('click', () => setMenu(!links.classList.contains('open')));
    links.addEventListener('click', (e) => { if (e.target.closest('a')) setMenu(false); });

    // Tanggal minimum = besok (dalam zona waktu pengunjung)
    const dateInput = document.getElementById('date');
    const toISODate = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    dateInput.min = toISODate(tomorrow);

    const form = document.getElementById('appointment');
    const RULES = {
      name: (v) => (v.trim().length >= 3 ? '' : 'Mohon isi nama lengkap.'),
      phone: (v) => (/^(\+62|62|0)\d{8,13}$/.test(v.replace(/[\s-]/g, '')) ? '' : 'Nomor telepon tidak valid.'),
      email: (v) => (/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()) ? '' : 'Format email tidak valid.'),
      area: (v) => (v ? '' : 'Pilih bidang masalah.'),
      date: (v) => {
        if (!v) return 'Pilih tanggal konsultasi.';
        if (v < dateInput.min) return 'Tanggal paling cepat besok.';
        const day = new Date(`${v}T00:00:00`).getDay();
        return day === 0 || day === 6 ? 'Konsultasi hanya tersedia Senin–Jumat.' : '';
      },
      summary: (v) => (v.trim().length >= 20 ? '' : 'Ringkasan minimal 20 karakter.'),
      consent: (_, el) => (el.checked ? '' : 'Persetujuan pemrosesan data diperlukan untuk melanjutkan.')
    };

    function setError(el, message) {
      const field = el.closest('.field');
      let error = field.querySelector('.error');
      if (!error) {
        error = Object.assign(document.createElement('p'), { className: 'error', id: `${el.id}-error` });
        field.append(error);
        el.setAttribute('aria-describedby', [el.getAttribute('aria-describedby'), error.id].filter(Boolean).join(' '));
      }
      error.textContent = message;
      el.setAttribute('aria-invalid', String(Boolean(message)));
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      let firstInvalid = null;
      for (const [name, rule] of Object.entries(RULES)) {
        const el = form.elements[name];
        const message = rule(el.value, el);
        setError(el, message);
        if (message && !firstInvalid) firstInvalid = el;
      }
      const status = document.getElementById('form-status');
      if (firstInvalid) {
        status.textContent = '';
        firstInvalid.focus();
        return;
      }
      // Kirim ke backend di sini. Pastikan koneksi HTTPS dan data disimpan dengan aman.
      const when = new Intl.DateTimeFormat('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(new Date(`${form.elements.date.value}T00:00:00`));
      status.textContent = `Terima kasih. Permintaan konsultasi untuk ${when} pukul ${form.elements.time.value} WIB sudah kami terima. Kami akan menghubungi Anda untuk konfirmasi.`;
      form.reset();
      form.querySelectorAll('[aria-invalid]').forEach((el) => el.removeAttribute('aria-invalid'));
    });

    form.addEventListener('input', (e) => {
      const el = e.target;
      if (el.getAttribute('aria-invalid') === 'true' && RULES[el.name]) setError(el, RULES[el.name](el.value, el));
    });

    document.getElementById('year').textContent = new Date().getFullYear();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Bidang praktik** → empat bidang. Perkara perdata diupayakan selesai damai lebih dulu, sejalan dengan Kode Etik Advokat Indonesia (KEAI) Pasal 4 huruf a.
- **Profil advokat** → tiga advokat beserta peran dan fokus praktiknya.
- **Alur konsultasi** → empat langkah, diakhiri kesepakatan tertulis tentang jasa dan honorarium (Pasal 21 UU No. 18 Tahun 2003 tentang Advokat).
- **Form janji konsultasi** → `RULES` dan `setError()` memvalidasi setiap kolom. Tanggal paling cepat besok dan hanya Senin–Jumat.
- **Sesuai etika profesi advokat:**
  - Tanpa janji hasil perkara (KEAI Pasal 4 huruf c) dan tanpa iklan berlebihan (KEAI Pasal 8 huruf b).
  - Menyebut bantuan hukum cuma-cuma (Pasal 22 UU Advokat) dan kerahasiaan klien (Pasal 19 UU Advokat).
  - Persetujuan pemrosesan data pribadi yang eksplisit (UU No. 27 Tahun 2022), pengingat agar tidak mengirim dokumen sensitif, dan penafian bahwa formulir tidak otomatis menimbulkan hubungan advokat dan klien.

**Sebelum dipakai:** ganti nama, profil, alamat, dan email contoh dengan data sebenarnya, lalu hubungkan form ke backend lewat HTTPS.

```html
<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Password Generator</title>
  <style>
    :root { --bg: #0b1020; --card: #141a2e; --field: #0f1426; --text: #e6e9f2; --muted: #8b93a7; --brand: #7c5cff; --border: #262e48; }
    *, *::before, *::after { box-sizing: border-box; }
    body { margin: 0; min-height: 100vh; display: grid; grid-template-columns: minmax(0, 480px); justify-content: center; align-content: center; padding: 1rem; font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; background: var(--bg); color: var(--text); }
    .card { padding: clamp(1.25rem, 5vw, 2rem); border-radius: 18px; background: var(--card); border: 1px solid var(--border); }
    h1 { margin: 0 0 1.25rem; font-size: 1.4rem; }
    :focus-visible { outline: 3px solid #b6a6ff; outline-offset: 2px; }

    .output { display: flex; gap: .5rem; }
    .output input { flex: 1; min-width: 0; padding: .9rem 1rem; border: 1px solid var(--border); border-radius: 12px; background: var(--field); color: var(--text); font: 1.15rem/1.2 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; letter-spacing: .03em; }
    .icon-btn { width: 52px; flex-shrink: 0; display: grid; place-items: center; border: 1px solid var(--border); border-radius: 12px; background: var(--field); color: var(--text); cursor: pointer; }
    .icon-btn:hover { border-color: var(--brand); }
    .copy-status { min-height: 1.4em; margin: .4rem 0 0; font-size: .85rem; color: #6ee7b7; }

    .strength { margin: 1rem 0 1.5rem; }
    .meter { display: grid; grid-template-columns: repeat(4, 1fr); gap: .35rem; }
    .meter span { height: 6px; border-radius: 999px; background: var(--border); transition: background-color .2s; }
    .strength p { display: flex; justify-content: space-between; margin: .5rem 0 0; font-size: .9rem; color: var(--muted); }
    .strength strong { color: var(--text); }

    .row { display: flex; justify-content: space-between; align-items: center; margin-bottom: .5rem; font-weight: 600; }
    .row output { font-variant-numeric: tabular-nums; color: var(--brand); font-size: 1.1rem; }
    input[type="range"] { width: 100%; accent-color: var(--brand); margin-bottom: 1.25rem; }
    fieldset { border: 0; padding: 0; margin: 0 0 1.5rem; display: grid; gap: .6rem; }
    legend { font-weight: 600; margin-bottom: .6rem; padding: 0; }
    .option { display: flex; align-items: center; gap: .65rem; padding: .7rem .9rem; border: 1px solid var(--border); border-radius: 10px; cursor: pointer; }
    .option input { width: 1.1rem; height: 1.1rem; accent-color: var(--brand); }
    .option small { margin-left: auto; color: var(--muted); font-family: ui-monospace, monospace; }
    .btn { width: 100%; padding: .9rem; border: 0; border-radius: 12px; background: var(--brand); color: #fff; font: inherit; font-weight: 700; cursor: pointer; }
    .btn:hover { filter: brightness(1.1); }
  </style>
</head>
<body>
  <main class="card">
    <h1>Password Generator</h1>

    <div class="output">
      <input id="password" readonly aria-label="Password yang dihasilkan" spellcheck="false">
      <button class="icon-btn" id="copy" type="button" aria-label="Salin password">
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
      </button>
    </div>
    <p class="copy-status" id="copy-status" role="status"></p>

    <div class="strength">
      <div class="meter" aria-hidden="true"><span></span><span></span><span></span><span></span></div>
      <p><span>Kekuatan: <strong id="strength-label"></strong></span><span id="entropy"></span></p>
    </div>

    <div class="row"><label for="length">Panjang</label><output id="length-value" for="length"></output></div>
    <input type="range" id="length" min="8" max="64" value="16">

    <fieldset>
      <legend>Karakter yang dipakai</legend>
      <label class="option"><input type="checkbox" data-set="lower" checked> Huruf kecil <small>a–z</small></label>
      <label class="option"><input type="checkbox" data-set="upper" checked> Huruf besar <small>A–Z</small></label>
      <label class="option"><input type="checkbox" data-set="digits" checked> Angka <small>0–9</small></label>
      <label class="option"><input type="checkbox" data-set="symbols" checked> Simbol <small>!@#$…</small></label>
      <label class="option"><input type="checkbox" id="no-ambiguous"> Hindari karakter mirip <small>I l 1 O 0</small></label>
    </fieldset>

    <button class="btn" id="generate" type="button">Buat Password Baru</button>
  </main>

  <script>
    const SETS = {
      lower: 'abcdefghijklmnopqrstuvwxyz',
      upper: 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
      digits: '0123456789',
      symbols: '!@#$%^&*()-_=+[]{};:,.?/'
    };
    const AMBIGUOUS = /[Il1O0o]/g;
    const LEVELS = [
      { min: 0, label: 'Lemah', color: '#ef4444' },
      { min: 50, label: 'Sedang', color: '#f59e0b' },
      { min: 75, label: 'Kuat', color: '#22c55e' },
      { min: 100, label: 'Sangat kuat', color: '#10b981' }
    ];

    const $ = (id) => document.getElementById(id);
    const setBoxes = [...document.querySelectorAll('[data-set]')];

    // Bilangan acak 0..max-1 dari crypto.getRandomValues dengan rejection sampling,
    // sehingga tidak ada bias seperti pada Math.random() atau operasi modulo biasa.
    function randomInt(max) {
      const limit = Math.floor(0x100000000 / max) * max;
      const buffer = new Uint32Array(1);
      do { crypto.getRandomValues(buffer); } while (buffer[0] >= limit);
      return buffer[0] % max;
    }

    function activePools() {
      const strip = $('no-ambiguous').checked;
      return setBoxes.filter((b) => b.checked).map((b) => (strip ? SETS[b.dataset.set].replace(AMBIGUOUS, '') : SETS[b.dataset.set]));
    }

    function generate() {
      const length = Number($('length').value);
      const pools = activePools();
      const all = pools.join('');
      // Pastikan setiap jenis karakter yang dipilih muncul minimal sekali, lalu acak urutannya.
      const chars = pools.map((pool) => pool[randomInt(pool.length)]);
      while (chars.length < length) chars.push(all[randomInt(all.length)]);
      for (let i = chars.length - 1; i > 0; i--) {
        const j = randomInt(i + 1);
        [chars[i], chars[j]] = [chars[j], chars[i]];
      }
      $('password').value = chars.join('');
      $('copy-status').textContent = '';
      updateStrength(length, all.length);
    }

    function updateStrength(length, poolSize) {
      const bits = Math.round(length * Math.log2(poolSize));
      const levelIndex = LEVELS.reduce((idx, level, i) => (bits >= level.min ? i : idx), 0);
      const level = LEVELS[levelIndex];
      $('strength-label').textContent = level.label;
      $('entropy').textContent = `±${bits} bit entropi`;
      document.querySelectorAll('.meter span').forEach((bar, i) => {
        bar.style.backgroundColor = i <= levelIndex ? level.color : '';
      });
    }

    async function copy() {
      const value = $('password').value;
      try {
        await navigator.clipboard.writeText(value);
        $('copy-status').textContent = 'Password disalin ke clipboard.';
      } catch (e) {
        // Clipboard API butuh HTTPS atau izin; sebagai cadangan, pilih teksnya agar bisa disalin manual.
        $('password').select();
        $('copy-status').textContent = 'Tekan Ctrl+C (atau Cmd+C) untuk menyalin.';
      }
    }

    // Minimal satu jenis karakter harus aktif
    setBoxes.forEach((box) => box.addEventListener('change', () => {
      if (!setBoxes.some((b) => b.checked)) box.checked = true;
      generate();
    }));
    $('no-ambiguous').addEventListener('change', generate);
    $('length').addEventListener('input', () => {
      $('length-value').textContent = $('length').value;
      generate();
    });
    $('generate').addEventListener('click', generate);
    $('copy').addEventListener('click', copy);

    $('length-value').textContent = $('length').value;
    generate();
  </script>
</body>
</html>
```

- **Panjang dan jenis karakter** → slider panjang dan pilihan huruf besar, huruf kecil, angka, dan simbol. Angka acak berasal dari `crypto.getRandomValues()` dengan rejection sampling (`randomInt()`), bukan `Math.random()`, dan setiap jenis yang dipilih dijamin muncul minimal sekali. Karakter yang mirip seperti `I l 1 O 0` bisa dikecualikan.
- **Indikator kekuatan** → `updateStrength()` menghitung entropi `panjang × log₂(jumlah karakter)` dan menampilkannya sebagai label serta meter empat tingkat.
- **Tombol salin** → memakai Clipboard API. Jika API itu tidak tersedia, misalnya karena halaman tidak dibuka lewat HTTPS, teks password dipilih otomatis agar bisa disalin manual.

